    -- DukeofHell [200002]
    ["STR_ID_DukeofHell[200002][Text1]"] = "<tip color=0xEEFFFF00 desc=Duke#of#Hell#was#born#with#the#ability#to#control#fire.#His#birth#was#a#secret,#but#said#a#son#of#the#Flame#Devastator#who#brought#disasters#to#the#land#300#years#ago.",
    ["STR_ID_DukeofHell[200002][Text2]"] = "~He#was#formerly#the#right-hand#man#of#the#King#of#Evil,#then#hid#in#the#central#plain#when#the#King#was#defeated.>Duke of Hell</tip>: ",
    ["STR_ID_DukeofHell[200002][Text3]"] = "A Windwalker? Just a joke. Your `wise` Elder Power has been a loser.",
    ["STR_ID_DukeofHell[200002][Text4]"] = "~So, you think you`re better than the loser? Well, prove yourself to me.",
    ["STR_ID_DukeofHell[200002][Option1]"] = "Go~to~hell!",

    -- ElderPower2 [200124]
    ["STR_ID_ElderPower2[200124][Text1]"] = "(The Elder Power sitting there looks like settling to meditation, but you know he will never come back to life.",
    ["STR_ID_ElderPower2[200124][Text2]"] = "~Remember, you must kill the Duke of Hell and protect the imperial mausoleum from the crisis. Keep your promise!)",
    ["STR_ID_ElderPower2[200124][Text3]"] = "@STR_COMMON[54]",
    ["STR_ID_ElderPower2[200124][Text4]"] = "@STR_COMMON[55]",
    ["STR_ID_ElderPower2[200124][Text5]"] = "Humph! If I were not injured earlier, the head of devil would not have a chance to hurt me. gattata1! You came at the right time.",
    ["STR_ID_ElderPower2[200124][Text6]"] = "~The head of devil has run into the deep tunnel after being hit by me. (Coughing)... Don`t let the devil escape!",
    ["STR_ID_ElderPower2[200124][Text7]"] = "(Coughing)... Don`t worry about me. Look, I`ll show you how to switch the combat style and help you...",
    ["STR_ID_ElderPower2[200124][Text8]"] = "~help you unblock the inner barriers. Promise... You should promise to defend the imperial mausoleum against the devils.",
    ["STR_ID_ElderPower2[200124][Text9]"] = "@STR_COMMON[54]",
    ["STR_ID_ElderPower2[200124][Text10]"] = "@STR_COMMON[55]",
    ["STR_ID_ElderPower2[200124][Text11]"] = "Good. It`s now your duty to defend... defend the honor of... Windwalker school. It may be too heavy for you, but...",
    ["STR_ID_ElderPower2[200124][Text12]"] = "~but I`m old, and I can no longer... no longer...  (The Elder spoke more and more quietly until he closed his eyes.)",
    ["STR_ID_ElderPower2[200124][Text13]"] = "(The Elder Power sitting there looks like settling to meditation, but you know he will never come back to life.",
    ["STR_ID_ElderPower2[200124][Text14]"] = "~Remember, you must kill the Duke of Hell and protect the imperial mausoleum from the crisis. Keep your promise!)",
    ["STR_ID_ElderPower2[200124][Option1]"] = "@STR_COMMON[56]",
    ["STR_ID_ElderPower2[200124][Option2]"] = "What~about~you?",
    ["STR_ID_ElderPower2[200124][Option3]"] = "I~promise.",
    ["STR_ID_ElderPower2[200124][Option4]"] = "No,~no,~my~Elder!",
    ["STR_ID_ElderPower2[200124][Option5]"] = "@STR_COMMON[56]",

    -- SisterYung2 [200058]
    ["STR_ID_SisterYung2[200058][Text1]"] = "Someone must be in danger. Hurry and check whether you can help!",
    ["STR_ID_SisterYung2[200058][Text2]"] = "<tip color=0xEEFFFF00 desc=Yung#is#your#lovely#fellow#sister#who#is#not#interested#in#kungfu#but#has#a#gift#for#cooking.",
    ["STR_ID_SisterYung2[200058][Text3]"] = "#Many#of#your#fellow#brothers#have#great#affection#for#her.>Sister Yung</tip>: ",
    ["STR_ID_SisterYung2[200058][Text4]"] = "Wow, my fellow brother! You killed these devils really fast. I know you won`t let me down.",
    ["STR_ID_SisterYung2[200058][Text5]"] = "<tip color=0xEEFFFF00 desc=Yung#is#your#lovely#fellow#sister#who#is#not#interested#in#kungfu#but#has#a#gift#for#cooking.",
    ["STR_ID_SisterYung2[200058][Text6]"] = "#Many#of#your#fellow#brothers#have#great#affection#for#her.>Sister Yung</tip>: ",
    ["STR_ID_SisterYung2[200058][Text7]"] = "Sorry, I don`t know that. It was me who told the Elder that some devils were running toward the imperial mausoleum. What can we do now?",
    ["STR_ID_SisterYung2[200058][Option1]"] = "@STR_COMMON[57]",
    ["STR_ID_SisterYung2[200058][Option2]"] = "Thanks.~Did~you~see~the~Elder?",
    ["STR_ID_SisterYung2[200058][Option3]"] = "I`ll~go~find~the~Elder.",

    -- SisterYung [20030]
    ["STR_ID_SisterYung[20030][Text1]"] = "Help! Help, my brother! These devils are quite furious. I`m not a match for them. Ow!",
    ["STR_ID_SisterYung[20030][Text2]"] = "My fellow brother, you should be very careful of them.",
    ["STR_ID_SisterYung[20030][Text3]"] = "My fellow brother, you should be very careful of them.",
    ["STR_ID_SisterYung[20030][Option1]"] = "Don`t~worry.~I`m~here.",
    ["STR_ID_SisterYung[20030][Option2]"] = "I`ll~take~care~of~them.",
    ["STR_ID_SisterYung[20030][Option3]"] = "I`ll~take~care~of~them.",

    -- ElderPower [20029]
    ["STR_ID_ElderPower[20029][Text1]"] = "@STR_COMMON[54]",
    ["STR_ID_ElderPower[20029][Text2]"] = "@STR_COMMON[55]",
    -- {0}=client.Player.Name
    ["STR_ID_ElderPower[20029][Text3]"] = "{0}? So good to have you here. (Coughing)... The devils disgracefully attacked us when the Chief was not in the camp.",
    ["STR_ID_ElderPower[20029][Text4]"] = "~Humph, we`ll never let them go that easily.",
    ["STR_ID_ElderPower[20029][Text5]"] = "@STR_COMMON[54]",
    ["STR_ID_ElderPower[20029][Text6]"] = "@STR_COMMON[55]",
    ["STR_ID_ElderPower[20029][Text7]"] = "TheBest01? So good to have you here. (Coughing)... The devils disgracefully attacked us when the Chief was not in the camp.",
    ["STR_ID_ElderPower[20029][Text8]"] = "~Humph, we`ll never let them go that easily.",
    ["STR_ID_ElderPower[20029][Text9]"] = "Yeah, I could have dodged the attacks, but I failed. It doesn`t matter. Listen, our school was endowed with the honor to guard",
    ["STR_ID_ElderPower[20029][Text10]"] = "~the imperial mausoleum for a hundred years. It`s almost finished, and we can`t jinx it. Wait, did you hear that?",
    ["STR_ID_ElderPower[20029][Option1]"] = "Are~you~hurt?",
    ["STR_ID_ElderPower[20029][Option2]"] = "Are~you~hurt?",
    ["STR_ID_ElderPower[20029][Option3]"] = "Someone~is~calling~for~help.",

    -- WindwalkerGuard [20028]
    ["STR_ID_WindwalkerGuard[20028][Text1]"] = "My fellow brother, you`re finally back! The devils suddenly attacked our camp. Many of our fellows",
    ["STR_ID_WindwalkerGuard[20028][Text2]"] = "~were... were killed... (sobbing)... Don`t worry about me. Hurry and give others some help!",
    ["STR_ID_WindwalkerGuard[20028][Option1]"] = "I~need~to~check~around~first.",
    ["STR_ID_WindwalkerGuard[20028][Option2]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option3]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option4]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option5]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option6]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option7]"] = "@STR_COMMON[58]",
    ["STR_ID_WindwalkerGuard[20028][Option8]"] = "I~need~to~check~around~first.",

    -- Matchmaker [30000]
    ["STR_ID_Matchmaker[30000][Text1]"] = "You~must~have~a~meteor~tear~and~a~meteor,~then~you~can~divorce.",
    ["STR_ID_Matchmaker[30000][Text2]"] = "Joe!~You~have~seen~him?~Where~is~he~now?~Is~everything~going~on~well~with~him?",
    ["STR_ID_Matchmaker[30000][Option1]"] = "I~shall~try~my~best!",
    ["STR_ID_Matchmaker[30000][Option2]"] = "OK.~I~shall~visit~her.",
    ["STR_ID_Matchmaker[30000][Option3]"] = "@STR_COMMON[59]",
    ["STR_ID_Matchmaker[30000][Option4]"] = "Here~you~are.",
    ["STR_ID_Matchmaker[30000][Option5]"] = "I~changed~my~mind.",
    ["STR_ID_Matchmaker[30000][Option6]"] = "Sorry,~I~cannot~tell~you.",
    ["STR_ID_Matchmaker[30000][Option7]"] = "Do~not~cry.",
    ["STR_ID_Matchmaker[30000][Option8]"] = "Do~not~ruin~the~meteor!",

