    -- SeasonDoor [4576]
    ["STR_ID_SeasonDoor[4576][Text1]"] = "These stone doors are all glowing with a strange aura. You can only break them with the Iron Poise.",
    ["STR_ID_SeasonDoor[4576][Text2]"] = "@STR_COMMON[71]",
