    -- TimeDoor [4575]
    ["STR_ID_TimeDoor[4575][Text1]"] = "These stone doors are cursed. They can only be opened with the Iron Poise, owned by Ye Sheng (192,212) on Bird Island.",
    ["STR_ID_TimeDoor[4575][Text2]"] = "@STR_COMMON[71]",
    ["STR_ID_TimeDoor[4575][Text3]"] = "@STR_COMMON[71]",
