    -- GhoulKong [4573]
    ["STR_ID_GhoulKong[4573][Text1]"] = "@STR_COMMON[76]",
    ["STR_ID_GhoulKong[4573][Text2]"] = "@STR_COMMON[76]",
    ["STR_ID_GhoulKong[4573][Text3]"] = "@STR_COMMON[76]",
    ["STR_ID_GhoulKong[4573][Text4]"] = "Well, according to your map, you are gonna meet quite a number of obstacles. A good beginning is half done. I shall",
    ["STR_ID_GhoulKong[4573][Text5]"] = "~escort you there. Anyway, that`s all an old man can do...",
    ["STR_ID_GhoulKong[4573][Text6]"] = "You found the right person. I`m just the most knowledgeable man, but the dungeon is very complicated. Without a map, no one knows where to get",
    ["STR_ID_GhoulKong[4573][Text7]"] = "~in or how to get out. So, what is your question?",
    ["STR_ID_GhoulKong[4573][Text8]"] = "The Star Tower was left by Frost Tang. It is said that it takes 4 clinkers, smelt from 4 weapons. They are the Glitter Sword,",
    ["STR_ID_GhoulKong[4573][Text9]"] = "~Annatto Blade, Wasp Spear, and Infernal Axe. With those and the three Tower pieces together, you can restore it in the Cauldro",
    ["STR_ID_GhoulKong[4573][Text10]"] = "Oh my! This isn`t an invocation! It`s the map to the Dungeon! The Dungeon, I`m telling you, is chock full of treasure...",
    ["STR_ID_GhoulKong[4573][Text11]"] = "~But it`s also full of hidden dangers and fierce monsters...",
    ["STR_ID_GhoulKong[4573][Text12]"] = "Maybe Yang Yun has the map to Dungeon. What can an old man like me do? I am useless...",
    ["STR_ID_GhoulKong[4573][Text13]"] = "Well, according to your map, you are gonna meet quite a number of obstacles. A good beginning is half done. I shall",
    ["STR_ID_GhoulKong[4573][Text14]"] = "~escort you there. Anyway, that`s all an old man can do...",
    ["STR_ID_GhoulKong[4573][Option1]"] = "I~have~some~questions.",
    ["STR_ID_GhoulKong[4573][Option2]"] = "@STR_COMMON[77]",
    ["STR_ID_GhoulKong[4573][Option3]"] = "I~want~to~ask~you~something.",
    ["STR_ID_GhoulKong[4573][Option4]"] = "@STR_COMMON[77]",
    ["STR_ID_GhoulKong[4573][Option5]"] = "@STR_COMMON[77]",
    ["STR_ID_GhoulKong[4573][Option6]"] = "@STR_COMMON[78]",
    ["STR_ID_GhoulKong[4573][Option7]"] = "I~got~a~Weird~Invocation.",
    ["STR_ID_GhoulKong[4573][Option8]"] = "How~to~smelt~the~Star~Tower?",
    ["STR_ID_GhoulKong[4573][Option9]"] = "Eh...~I~forgot.",
    ["STR_ID_GhoulKong[4573][Option10]"] = "There~is~another~thing.",
    ["STR_ID_GhoulKong[4573][Option11]"] = "Unbelievable.",
    ["STR_ID_GhoulKong[4573][Option12]"] = "No~pain,~no~gain.",
    ["STR_ID_GhoulKong[4573][Option13]"] = "@STR_COMMON[79]",
    ["STR_ID_GhoulKong[4573][Option14]"] = "I`m~glad~you~said~it.",
    ["STR_ID_GhoulKong[4573][Option15]"] = "@STR_COMMON[78]",

    -- Cauldron [4578]
    ["STR_ID_Cauldron[4578][Text1]"] = "Everyone wants to be immortal, but what is the meaning, if you are alone in the world. What do you say?",
    ["STR_ID_Cauldron[4578][Text2]"] = "Everyone wants to be immortal, but what is the meaning, if you are alone in the world. What do you say?",
    ["STR_ID_Cauldron[4578][Text3]"] = "@STR_COMMON[80]",
    ["STR_ID_Cauldron[4578][Text4]"] = "Love built on beauty fades all too quickly. Pity, that Frost Tang was never happy... To restore the Tower, you need to collect",
    ["STR_ID_Cauldron[4578][Text5]"] = "~Glitter Sword, Annatto Blade, Wasp Spear, and Infernal Axe, smelt them and meld 4 clinkers with the 3 pieces in the Cauldron. So, how may I help you?",
    ["STR_ID_Cauldron[4578][Text6]"] = "Now that the Star Tower has been restored, you should leave this dangerous place right away. Hurry up and return to Bird Island for Sugar Tang.",
    ["STR_ID_Cauldron[4578][Text7]"] = "@STR_COMMON[80]",
    ["STR_ID_Cauldron[4578][Text8]"] = "Love built on beauty fades all too quickly. Pity, that Frost Tang was never happy... To restore the Tower, you need to collect",
    ["STR_ID_Cauldron[4578][Text9]"] = "~Glitter Sword, Annatto Blade, Wasp Spear, and Infernal Axe, smelt them and meld 4 clinkers with the 3 pieces in the Cauldron. So, how may I help you?",
    ["STR_ID_Cauldron[4578][Text10]"] = "You`ve got the Fire Clinker, Earth Clinker, Earth Clinker, and Wood Clinker.",
    ["STR_ID_Cauldron[4578][Text11]"] = "@STR_COMMON[81]",
    ["STR_ID_Cauldron[4578][Text12]"] = "@STR_COMMON[81]",
    ["STR_ID_Cauldron[4578][Text13]"] = "@STR_COMMON[81]",
    ["STR_ID_Cauldron[4578][Text14]"] = "@STR_COMMON[81]",
    ["STR_ID_Cauldron[4578][Text15]"] = "@STR_COMMON[80]",
    ["STR_ID_Cauldron[4578][Text16]"] = "It takes a combination of the five elements of fire, earth, water, metal, and wood to restore the talisman.",
    ["STR_ID_Cauldron[4578][Text17]"] = "~Wait a moment. The Star Tower is almost completely restored.",
    ["STR_ID_Cauldron[4578][Text18]"] = "You will have all three Tower Splinters after defeating the ghost of Yang Feng. Don`t stop until he`s dead again!",
    ["STR_ID_Cauldron[4578][Text19]"] = "@STR_COMMON[82]",
