    -- BlockStone [4603]
    ["STR_ID_BlockStone[4603][Text1]"] = "The entrance has been blocked! You need to kill 20 Vicious Rats, so you`ll be able to get out of here!",
    ["STR_ID_BlockStone[4603][Option1]"] = "Damned!",

    -- KunlunWanderer [4583]
    ["STR_ID_KunlunWanderer[4583][Text1]"] = "You must have heard about the Kunlun Stone! Guess what I found out? The stone is the Poison Fang of the Viper!",
    ["STR_ID_KunlunWanderer[4583][Text2]"] = "~When dissolved in the Kunlun Liquid, it can be used to dye Tang Silk. Haha, I just happened to have the liquid.",
    ["STR_ID_KunlunWanderer[4583][Text3]"] = "Hey, glad to see you alive! How is your adventure in the Viper Cave? You know, to dye the Tang Silk, you should have the Sacred Water!",
    ["STR_ID_KunlunWanderer[4583][Text4]"] = "~That`s made from the Poison Fang and the Kunlun Liquid.",
    ["STR_ID_KunlunWanderer[4583][Text5]"] = "As I mentioned before, you should have the Sacred Water composed by the Kunlun Liquid and the Poison Fang to dye the Tang Silk. I`ll give you the",
    ["STR_ID_KunlunWanderer[4583][Text6]"] = "~Kunlun Liquid, if you can get the Poison Fang from the Viper in the Viper Cave. So, you are going to the Viper Cave?",
    ["STR_ID_KunlunWanderer[4583][Text7]"] = "Finally, we have discovered the secret of the Tang Silk! But it seems another mystery has emerged...",
    ["STR_ID_KunlunWanderer[4583][Text8]"] = "~Things are far from over.",
    ["STR_ID_KunlunWanderer[4583][Text9]"] = "Someone must have told you something about the Kunlun Stone. But you know what it is? It`s just the Posion Fang of the Viper!",
    ["STR_ID_KunlunWanderer[4583][Text10]"] = "~Combined with the Kunlun Liquid, it can be used to dye Tang Silk.",
    ["STR_ID_KunlunWanderer[4583][Text11]"] = "Then, what are you doing here? Shouldn`t you send the Poem Silk to Villager Chou, now?",
    ["STR_ID_KunlunWanderer[4583][Text12]"] = "Oh, Sacred Water...It can be used to dye Tang Silk... It`s said a mysterious secret will appear right away!",
    ["STR_ID_KunlunWanderer[4583][Text13]"] = "Oh, Sacred Water...It can be used to dye Tang Silk... It`s said a mysterious secret will appear right away!",
    ["STR_ID_KunlunWanderer[4583][Text14]"] = "Now, merge the Poison Fang with the Kunlun Liquid. That`s how Sacred Water is made. Do it, now!",
    ["STR_ID_KunlunWanderer[4583][Text15]"] = "So, you`ve obtained the Poison Fang? Great! Here is the Kunlun Liquid. After dissolving the fang into the liquid, you`ll receive the Sacred Water.",
    ["STR_ID_KunlunWanderer[4583][Text16]"] = "@STR_COMMON[87]",
    ["STR_ID_KunlunWanderer[4583][Text17]"] = "@STR_COMMON[88]",
    ["STR_ID_KunlunWanderer[4583][Text18]"] = "Then, what are you doing here? Shouldn`t you send the Poem Silk to Villager Chou, now?",
    ["STR_ID_KunlunWanderer[4583][Text19]"] = "Stop kidding me! I just saw the Poem Silk in your inventory. Hurry to take it to Villager Chou!",
    ["STR_ID_KunlunWanderer[4583][Text20]"] = "@STR_COMMON[89]",
    ["STR_ID_KunlunWanderer[4583][Text21]"] = "@STR_COMMON[89]",
    ["STR_ID_KunlunWanderer[4583][Text22]"] = "@STR_COMMON[87]",
    ["STR_ID_KunlunWanderer[4583][Text23]"] = "@STR_COMMON[88]",
    ["STR_ID_KunlunWanderer[4583][Text24]"] = "Do you mean the Tang Silk owned by Villager Chou?",
    ["STR_ID_KunlunWanderer[4583][Text25]"] = "Without Tang Silk, everything will be in vain. Find Villager Chou in Maple Forest (788,456) now. I know his grandpa quite well.",
    ["STR_ID_KunlunWanderer[4583][Text26]"] = "@STR_COMMON[87]",
    ["STR_ID_KunlunWanderer[4583][Text27]"] = "@STR_COMMON[88]",
    ["STR_ID_KunlunWanderer[4583][Text28]"] = "Come on! 10,000 silvers wouldn`t be so hard for you. Make sure you bring enough money with you!",
    ["STR_ID_KunlunWanderer[4583][Option1]"] = "I~have~the~Tang~Silk.",
    ["STR_ID_KunlunWanderer[4583][Option2]"] = "@STR_COMMON[90]",
    ["STR_ID_KunlunWanderer[4583][Option3]"] = "Now~what~should~I~do?",
    ["STR_ID_KunlunWanderer[4583][Option4]"] = "@STR_COMMON[65]",
    ["STR_ID_KunlunWanderer[4583][Option5]"] = "Yeah,~but~how~to~get~there?",
    ["STR_ID_KunlunWanderer[4583][Option6]"] = "Viper?~I`ll~be~killed!",
    ["STR_ID_KunlunWanderer[4583][Option7]"] = "I`ve~dyed~the~Tang~Silk.",
    ["STR_ID_KunlunWanderer[4583][Option8]"] = "@STR_COMMON[90]",
    ["STR_ID_KunlunWanderer[4583][Option9]"] = "@STR_COMMON[90]",
    ["STR_ID_KunlunWanderer[4583][Option10]"] = "@STR_COMMON[91]",
    ["STR_ID_KunlunWanderer[4583][Option11]"] = "I~lost~the~Poem~Silk.",
    ["STR_ID_KunlunWanderer[4583][Option12]"] = "@STR_COMMON[92]",
    ["STR_ID_KunlunWanderer[4583][Option13]"] = "@STR_COMMON[92]",
    ["STR_ID_KunlunWanderer[4583][Option14]"] = "Don`t~talk~while~I`m~pouring.",
    ["STR_ID_KunlunWanderer[4583][Option15]"] = "@STR_COMMON[14]",
    ["STR_ID_KunlunWanderer[4583][Option16]"] = "@STR_COMMON[93]",
    ["STR_ID_KunlunWanderer[4583][Option17]"] = "@STR_COMMON[91]",
    ["STR_ID_KunlunWanderer[4583][Option18]"] = "I~lost~the~Poem~Silk.",
    ["STR_ID_KunlunWanderer[4583][Option19]"] = "@STR_COMMON[68]",
    ["STR_ID_KunlunWanderer[4583][Option20]"] = "@STR_COMMON[94]",
    ["STR_ID_KunlunWanderer[4583][Option21]"] = "@STR_COMMON[94]",
    ["STR_ID_KunlunWanderer[4583][Option22]"] = "@STR_COMMON[93]",
    ["STR_ID_KunlunWanderer[4583][Option23]"] = "Yeah,~he~gave~me~the~silk.",
    ["STR_ID_KunlunWanderer[4583][Option24]"] = "I`ll~visit~him,~now.",
    ["STR_ID_KunlunWanderer[4583][Option25]"] = "@STR_COMMON[93]",
