    -- MrLoneliness [4595]
    ["STR_ID_MrLoneliness[4595][Text1]"] = "Yeah, the Heaven Fan is mine. How did you find it? You came for the poem book, right? So many people have asked",
    ["STR_ID_MrLoneliness[4595][Text2]"] = "~me about it, but you`re the only one who gave me the Heaven Fan. So, here`s the book. Take it to Sugar Tang, and be gone!",
    ["STR_ID_MrLoneliness[4595][Text3]"] = "@STR_COMMON[108]",
    ["STR_ID_MrLoneliness[4595][Text4]"] = "Blech! Look what evil you have brought out! Shouldn`t you sweep them out of my house?",
    ["STR_ID_MrLoneliness[4595][Text5]"] = "@STR_COMMON[108]",
    ["STR_ID_MrLoneliness[4595][Text6]"] = "@STR_COMMON[108]",
    ["STR_ID_MrLoneliness[4595][Option1]"] = "With~pleasure!",
    ["STR_ID_MrLoneliness[4595][Option2]"] = "@STR_COMMON[109]",
    ["STR_ID_MrLoneliness[4595][Option3]"] = "@STR_COMMON[110]",
    ["STR_ID_MrLoneliness[4595][Option4]"] = "Oh,~my!",
