    ["STR_ID_VillagerChou[4582][Text51]"] = "@STR_COMMON[120]",
    ["STR_ID_VillagerChou[4582][Text52]"] = "Mmm, that`s good. I do like snakes, but only after they`re in my belly. It so happens, that I am the man you`re looking for...",
    ["STR_ID_VillagerChou[4582][Text53]"] = "@STR_COMMON[119]",
