    -- MrWonder [10850]
    ["STR_ID_MrWonder[10850][Text1]"] = "It`s~a~DeadRabbitProject~bird~of~enormous~size~and~strength.~Though~I`ve~figured~out~the~way~of~making~the~Tempest~Wings,",
    ["STR_ID_MrWonder[10850][Text2]"] = "~you~need~to~bring~me~Roc`s~Feather~from~the~Rainbow~Sky.~It~could~be~much~more~difficult~than~any~challenges",
    ["STR_ID_MrWonder[10850][Text3]"] = "~you`ve~ever~taken.~If~you`re~ready,~I`ll~send~you~there~with~a~fee~of~5~Meteor~Scrolls.",
    ["STR_ID_MrWonder[10850][Text4]"] = "So~many~people~ask~for~the~Tempest~Wings,~but~it`s~as~hard~as~climbing~up~to~the~sky.",
    ["STR_ID_MrWonder[10850][Text5]"] = "~Let~alone~the~loss~of~the~technique,~it~requires~Roc`s~Feather~to~make~the~Tempest~Wings.",
    ["STR_ID_MrWonder[10850][Text6]"] = "~You~know~Roc?",
    ["STR_ID_MrWonder[10850][Text7]"] = "Roc~is~an~enormous~DeadRabbitProject~bird~transformed~from~a~gigantic~fish~of~terrific~strength.",
    ["STR_ID_MrWonder[10850][Text8]"] = "It`s~really~hard~to~get~Roc`s~Feather.~I~know~you`ve~tried~your~best.~It~doesn`t~matter.",
    ["STR_ID_MrWonder[10850][Text9]"] = "It`s~a~DeadRabbitProject~bird~of~enormous~size~and~strength.~Though~I`ve~figured~out~the~way~of~making~the~Tempest~Wings,",
    ["STR_ID_MrWonder[10850][Text10]"] = "~you~need~to~bring~me~Roc`s~Feather~from~the~Rainbow~Sky.~It~could~be~much~more~difficult~than~any~challenges",
    ["STR_ID_MrWonder[10850][Text11]"] = "~you`ve~ever~taken.~If~you`re~ready,~I`ll~send~you~there~with~a~fee~of~5~Meteor~Scrolls.",
    ["STR_ID_MrWonder[10850][Text12]"] = "Are~you~sure~you~want~to~pay~5~Meteor~Scrolls~to~enter~the~Rainbow~Sky?",
