    ["STR_ID_Celestine[20005][Option7]"] = "How~to~get~CelestialStone?",
    ["STR_ID_Celestine[20005][Option8]"] = "Forget~it.",
    ["STR_ID_Celestine[20005][Option9]"] = "What~is~Clean~Water?",
    ["STR_ID_Celestine[20005][Option10]"] = "It~is~difficult.",
    ["STR_ID_Celestine[20005][Option11]"] = "What~are~gems~used~for?",
    ["STR_ID_Celestine[20005][Option12]"] = "I~will~collect~them~now.",
    ["STR_ID_Celestine[20005][Option13]"] = "I~changed~my~mind.",
    ["STR_ID_Celestine[20005][Option14]"] = "But~what?",
    ["STR_ID_Celestine[20005][Option15]"] = "@STR_COMMON[127]",
    ["STR_ID_Celestine[20005][Option16]"] = "I~will~give~up.",
    ["STR_ID_Celestine[20005][Option17]"] = "I~see.~Thank~you.",
    ["STR_ID_Celestine[20005][Option18]"] = "@STR_COMMON[128]",
    ["STR_ID_Celestine[20005][Option19]"] = "OK.~Thank~you.",
    ["STR_ID_Celestine[20005][Option20]"] = "I~will~get~it~ready.",
