    ["STR_ID_MasterMoMo[4702][Text15]"] = "What a wild desert!",
    ["STR_ID_MasterMoMo[4702][Text16]"] = "@STR_COMMON[139]",
    ["STR_ID_MasterMoMo[4702][Text17]"] = "@STR_COMMON[140]",
