    -- LeadWrangler [8616]
    ["STR_ID_LeadWrangler[8616][Text1]"] = "Hey,~there!~Let~me~tell~you~about~the~joys~of~the~Wrangler!~Wranglers~are~able~to~equip~special~armor~on~their~mounts.~As~their~Sub-Class~level~improves,",
    ["STR_ID_LeadWrangler[8616][Text2]"] = "~their~Max~HP~increases.~Isn`t~it~great?~Would~you~like~to~join~us?",
    ["STR_ID_LeadWrangler[8616][Text3]"] = "You`re~not~a~Wrangler~yet,~and~can`t~get~promoted.~Would~you~like~to~become~a~Wrangler?",
    ["STR_ID_LeadWrangler[8616][Text4]"] = "To~get~promoted~to~Phase~2~and~be~able~to~equip~better~mount~armor,~your~character~should~reach~Level~90~and~your~Sub-Class~reach~Level~2.",
    ["STR_ID_LeadWrangler[8616][Text5]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text6]"] = "To~get~promoted~to~Phase~3~and~be~able~to~equip~better~mount~armor,~your~character~should~reach~Level~110~and~your~Sub-Class~at~Level~3.",
    ["STR_ID_LeadWrangler[8616][Text7]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text8]"] = "To~get~promoted~to~Phase~4~and~be~able~to~equip~better~mount~armor,~your~character~should~reach~Level~120~and~your~Sub-Class~at~Level~4.",
    ["STR_ID_LeadWrangler[8616][Text9]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text10]"] = "To~get~promoted~to~Phase~5~and~be~able~to~equip~better~mount~armor,~you~should~meet~the~following~requirements:~Be~Reborn~once,~Character~Level~90,~and~Sub-Class~Level~5.",
    ["STR_ID_LeadWrangler[8616][Text11]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text12]"] = "To~get~promoted~to~Phase~6~and~be~able~to~equip~better~mount~armor,~you~should~meet~the~following~requirements:~Be~Reborn~once,~Character~Level~110,~and~Sub-Class~Level~6.",
    ["STR_ID_LeadWrangler[8616][Text13]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text14]"] = "To~get~promoted~to~Phase~7~and~be~able~to~equip~better~mount~armor,~you~should~meet~the~following~requirements:~Be~Reborn~once,~Character~Level~120,~and~Sub-Class~Level~7.",
    ["STR_ID_LeadWrangler[8616][Text15]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text16]"] = "To~get~promoted~to~Phase~8~and~be~able~to~equip~better~mount~armor,~you~should~meet~the~following~requirements:~Be~Reborn~twice,~Character~Level~120,~and~Sub-Class~Level~8.",
    ["STR_ID_LeadWrangler[8616][Text17]"] = "@STR_COMMON[213]",
    ["STR_ID_LeadWrangler[8616][Text18]"] = "To~get~promoted~to~Phase~9~and~be~able~to~equip~better~mount~armor,~you~should~meet~the~following~requirements:~Be~Reborn~twice,~Character~Level~130,~and~Sub-Class~Level~9.",
