    ["STR_ID_LeadWrangler[8616][Text62]"] = "@STR_COMMON[214]",
    ["STR_ID_LeadWrangler[8616][Text63]"] = "Congratulations!~You`ve~been~promoted~to~a~P2~Wrangler!",
    ["STR_ID_LeadWrangler[8616][Text64]"] = "Each~Sub-Class~has~9~Phases.~The~higher~the~phase~is,~the~more~bonus~effects~you~will~get.",
    ["STR_ID_LeadWrangler[8616][Text65]"] = "~But~keep~in~mind~that~these~Sub-Classes~also~have~a~level~system,~and~you~need~to~level~them~up~before~you~can~get~promoted.~You~can~level~up~your~Sub-Class~by~gaining~Study~Points.",
    ["STR_ID_LeadWrangler[8616][Text66]"] = "Well,~the~only~way~to~get~those~points~is~to~read~the~Sub-Class~books,~such~as~the~Diligence~Book.~When~you`ve~gained~enough~Study~Points,",
    ["STR_ID_LeadWrangler[8616][Text67]"] = "~open~the~Sub-Class~sheet~from~the~character~panel~and~level~up~the~Sub-Class,~there.~Monsters~in~the~wild~are~always~bothering~young~adventurers,",
    ["STR_ID_LeadWrangler[8616][Text68]"] = "~so~you~might~find~some~books~after~you~kill~them.",
    ["STR_ID_LeadWrangler[8616][Text69]"] = "Wranglers~are~able~to~equip~special~armor~on~their~mounts.~If~you`ve~reached~Level~40,~you~can~pay~40~Saddles~or~800~Study~Points~to~join~us.~",
    ["STR_ID_LeadWrangler[8616][Text70]"] = "~After~being~a~Wrangler,~you~can~enhance~your~sub-class~skill~on~`Status`~sheet.~Remember,~a~certain~sub-class~level~is~required~to~promote~the~phase~of~your~sub-class.",
    ["STR_ID_LeadWrangler[8616][Text71]"] = "@STR_COMMON[172]",
    ["STR_ID_LeadWrangler[8616][Text72]"] = "I`m~sorry,~but~you~have~to~reach~at~least~Level~70~to~join~our~fine~group~of~adventurers.",
    ["STR_ID_LeadWrangler[8616][Text73]"] = "@STR_COMMON[173]",
