    -- SubClassManager [8591]
    ["STR_ID_SubClassManager[8591][Text1]"] = "In addition to the existing 7 classes, there are 7 sub-classes for you to choose, which will grant you many bonus effects.",
    ["STR_ID_SubClassManager[8591][Text2]"] = " The 7 sub-classes are Apothecary, Chi Master, Martial Artist, Warlock, Sage, Performer, Lead Wrangler. Do you want to choose a sub-class to",
    ["STR_ID_SubClassManager[8591][Text3]"] = "~enhance the strength of your character?",
    ["STR_ID_SubClassManager[8591][Option1]"] = "Sub-Class~Hall",
    ["STR_ID_SubClassManager[8591][Option2]"] = "See~you~later.",

    -- ArenaGuard [4432]
    ["STR_ID_ArenaGuard[4432][Text1]"] = "A suited weapon is a thing that you can`t do without nowadays. I keep faith in it.",
    ["STR_ID_ArenaGuard[4432][Option1]"] = "Attractive.",

    -- IronsmithChou [4434]
    ["STR_ID_IronsmithChou[4434][Option1]"] = "Sub-Class~Hall",

    -- BirdExorcist [300010]
    ["STR_ID_BirdExorcist[300010][Text1]"] = "Sigh, I should have felt the danger earlier. The Ancient Devil sealed away a thousand years ago is gonna wake up! I`m afraid a war is inevitable.",
    ["STR_ID_BirdExorcist[300010][Text2]"] = "Bring your people together, and collect amulets of 7 classes by completing the given tests in the Ancient Island. If you have Ninjas, Monks, Saints or Pirates in your team,",
    ["STR_ID_BirdExorcist[300010][Text3]"] = "~they`ll get the amulets after finishing the test of any classes.",
    ["STR_ID_BirdExorcist[300010][Text4]"] = "If your team holds a Monk Amulet, use that amulet to combine all the other amulets. If not, ask any one in your team to take all the 7 amulets and turn on a shining yellow switch",
    ["STR_ID_BirdExorcist[300010][Text5]"] = "~to bring out the Ancient Devil. Kill the devil before its power fully recovered! So, what do you say?",
    ["STR_ID_BirdExorcist[300010][Option1]"] = "@STR_COMMON[127]",
    ["STR_ID_BirdExorcist[300010][Option2]"] = "Goodness!~I`d~better~flee!",
    ["STR_ID_BirdExorcist[300010][Option3]"] = "Okay,~what~to~do~next?",
    ["STR_ID_BirdExorcist[300010][Option4]"] = "I~love~challenge!",
    ["STR_ID_BirdExorcist[300010][Option5]"] = "I~need~a~break!",

    -- CommanderKerry [4707]
    ["STR_ID_CommanderKerry[4707][Text1]"] = "@STR_COMMON[218]",
    ["STR_ID_CommanderKerry[4707][Text2]"] = "@STR_COMMON[218]",
    ["STR_ID_CommanderKerry[4707][Text3]"] = "@STR_COMMON[218]",
    ["STR_ID_CommanderKerry[4707][Text4]"] = "@STR_COMMON[218]",
    ["STR_ID_CommanderKerry[4707][Text5]"] = "@STR_COMMON[219]",
    ["STR_ID_CommanderKerry[4707][Text6]"] = "@STR_COMMON[219]",
    ["STR_ID_CommanderKerry[4707][Text7]"] = "I don`t even know who you are. Why do you want to kill me?",
    ["STR_ID_CommanderKerry[4707][Text8]"] = "Be careful and be quick...Step into 1 of the eyes of the Maze Puzzle in 10 seconds and I will send you out to Felix...",
    ["STR_ID_CommanderKerry[4707][Text9]"] = "Be careful and be quick...Step into 2 of the eyes of the Maze Puzzle in 10 seconds and I will send you out to Felix...",
    ["STR_ID_CommanderKerry[4707][Text10]"] = "Be careful and be quick...Step into 3 of the eyes of the Maze Puzzle in 10 seconds and I will send you out to Felix...",
    ["STR_ID_CommanderKerry[4707][Text11]"] = "Be careful and be quick...Step into 4 of the eyes of the Maze Puzzle in 10 seconds and I will send you out to Felix...",
    ["STR_ID_CommanderKerry[4707][Text12]"] = "What did you come for, young hero?",
    ["STR_ID_CommanderKerry[4707][Text13]"] = "Oh, Felix! My son! He is still alive. I miss him so much!",
    ["STR_ID_CommanderKerry[4707][Text14]"] = "It is a long story. Many years ago, I mistakenly killed Felix`s birth parents, that is why I took to raise him up. Felix finally got to know that it was me,",
    ["STR_ID_CommanderKerry[4707][Text15]"] = "~and he will never forgive me. I know that.",
    ["STR_ID_CommanderKerry[4707][Text16]"] = "@STR_COMMON[219]",
    ["STR_ID_CommanderKerry[4707][Text17]"] = "@STR_COMMON[219]",
    ["STR_ID_CommanderKerry[4707][Text18]"] = "For my life? What makes you so cocky...Hey, see what, if you could step into 5 of the eyes of the Maze Puzzle within 10 seconds",
    ["STR_ID_CommanderKerry[4707][Text19]"] = "~I will give you a chance.",
    ["STR_ID_CommanderKerry[4707][Option1]"] = "@STR_COMMON[220]",
    ["STR_ID_CommanderKerry[4707][Option2]"] = "@STR_COMMON[66]",
    ["STR_ID_CommanderKerry[4707][Option3]"] = "@STR_COMMON[220]",
    ["STR_ID_CommanderKerry[4707][Option4]"] = "@STR_COMMON[66]",
    ["STR_ID_CommanderKerry[4707][Option5]"] = "@STR_COMMON[220]",
    ["STR_ID_CommanderKerry[4707][Option6]"] = "@STR_COMMON[66]",
    ["STR_ID_CommanderKerry[4707][Option7]"] = "@STR_COMMON[220]",
    ["STR_ID_CommanderKerry[4707][Option8]"] = "@STR_COMMON[66]",
    ["STR_ID_CommanderKerry[4707][Option9]"] = "@STR_COMMON[136]",
    ["STR_ID_CommanderKerry[4707][Option10]"] = "@STR_COMMON[136]",
    ["STR_ID_CommanderKerry[4707][Option11]"] = "For~Felix!",
    ["STR_ID_CommanderKerry[4707][Option12]"] = "@STR_COMMON[221]",
    ["STR_ID_CommanderKerry[4707][Option13]"] = "@STR_COMMON[221]",
    ["STR_ID_CommanderKerry[4707][Option14]"] = "@STR_COMMON[221]",
    ["STR_ID_CommanderKerry[4707][Option15]"] = "@STR_COMMON[221]",
    ["STR_ID_CommanderKerry[4707][Option16]"] = "For~your~life.",
    ["STR_ID_CommanderKerry[4707][Option17]"] = "What?",
