    -- GeneralPakMap3 [10603]
    ["STR_ID_GeneralPakMap3[10603][Text1]"] = "It`s~the~end.~Though~the~Flame~Devastator~was~weakened,~it`ll~still~fierce~enough~to~smash~the~world.",
    ["STR_ID_GeneralPakMap3[10603][Text2]"] = "~Look,~you~need~awaken~the~Solar~Blade`s~spirit,~and~then~combine~the~spirit~with~your~main~weapon~(must~be~universal~one-handed)~to~create~an~Epic~Weapon.",
    ["STR_ID_GeneralPakMap3[10603][Text3]"] = "~With~the~power~of~the~Epic~Weapon,~we~may~behead~the~Flame~Devastator.",
    ["STR_ID_GeneralPakMap3[10603][Text4]"] = "The~Flame~Devastator~has~been~weakened,~but~I`m~afraid~normal~weapons~can`t~wound~this~demon.",
    ["STR_ID_GeneralPakMap3[10603][Text5]"] = "~Take~my~Solar~Blade!~If~you`re~able~to~awaken~its~spirit,~and~combine~the~spirit~with~your~main~weapon~(must~be~universal~one-handed)",
    ["STR_ID_GeneralPakMap3[10603][Text6]"] = "~to~create~an~Epic~Weapon,~you`ll~achieve~a~divine~power.",
    ["STR_ID_GeneralPakMap3[10603][Text7]"] = "What~a~miracle!~The~Solar~signed~a~blood~contract~with~you!~But~for~this~reason,~the~Flame~Devastator~can~be~eliminated.",
    ["STR_ID_GeneralPakMap3[10603][Text8]"] = "~Now,~only~you~can~summon~the~spirit~of~Solar~Blade.~From~now~on,~you`re~the~owner~of~this~Epic~Weapon!",
    ["STR_ID_GeneralPakMap3[10603][Text9]"] = "You~inventory~is~full.~Make~some~room~for~the~Solar~Blade,~first.",
