    -- GeneralPak [10581]
    ["STR_ID_GeneralPak[10581][Text1]"] = "It~seems~Monk~Misery~has~united~with~the~Flame~Devastator~for~a~long~time.~They~are~getting~fiery.",
    ["STR_ID_GeneralPak[10581][Text2]"] = "~I`m~afraid~they`ll~carry~out~the~plan~earlier.~See,~it`s~not~wise~to~deal~with~an~unknown~thing.",
    ["STR_ID_GeneralPak[10581][Text3]"] = "~Go~collect~possible~information~from~Monk~Misery,~first.",
    ["STR_ID_GeneralPak[10581][Text4]"] = "How~could~those~Ghost~Reavers~escape~from~the~Evil~Array~when~you~were~enhancing~its~power?",
    ["STR_ID_GeneralPak[10581][Text5]"] = "~The~Monk~Misery~looked~quite~suspicious~when~you~were~killing~the~Ghost~Reavers.",
    ["STR_ID_GeneralPak[10581][Text6]"] = "~He~was~reciting~some~strange~spells~and~talking~to~the~Flame~Devastator.",
    ["STR_ID_GeneralPak[10581][Text7]"] = "Though~the~Evil~Array~has~been~enhanced,~there~are~18~Ghost~Reavers~from~the~Flame~Devastator`s~army~sneaking~into~the~world.",
    ["STR_ID_GeneralPak[10581][Text8]"] = "~Be~careful,~those~Ghost~Reavers~are~trying~to~destroy~the~array.~They~should~die.",
    ["STR_ID_GeneralPak[10581][Text9]"] = "Though~the~Evil~Array~has~been~enhanced,~there~are~18~Ghost~Reavers~from~the~Flame~Devastator`s~army~sneaking~into~the~world.",
    ["STR_ID_GeneralPak[10581][Text10]"] = "~Be~careful,~those~Ghost~Reavers~are~trying~to~destroy~the~array.~They~should~die.",
    ["STR_ID_GeneralPak[10581][Text11]"] = "Years~ago,~the~Flame~Devastator,~a~vicious~demon,~terrorized~Twin~City.~At~that~time,~a~prominent~taoist~spent~out~his~power~and~built~the~Evil~Array",
    ["STR_ID_GeneralPak[10581][Text12]"] = "~to~seal~the~gate~of~evils.~However,~with~time~goes~by,~the~Evil~Array~becomes~weak~and~the~sealed~Flame~Devastator~is~getting~unrest.",
    ["STR_ID_GeneralPak[10581][Text13]"] = "~I`m~afraid~the~returning~of~the~Flame~Devastator~will~push~Twin~City~into~hell,~again.",
    ["STR_ID_GeneralPak[10581][Text14]"] = "What~a~shame!~I`m~the~General,~but~I~were~quite~unaware~of~that.~Anyway,~we~have~to~stop~them~no~matter~what~they~were~plotting.",
    ["STR_ID_GeneralPak[10581][Text15]"] = "It~seems~Monk~Misery~has~united~with~the~Flame~Devastator~for~a~long~time.~They~are~getting~fiery.",
    ["STR_ID_GeneralPak[10581][Text16]"] = "~I`m~afraid~they`ll~carry~out~the~plan~earlier.~See,~it`s~not~wise~to~deal~with~an~unknown~thing.",
    ["STR_ID_GeneralPak[10581][Text17]"] = "~Go~collect~possible~information~from~Monk~Misery,~first.",
    ["STR_ID_GeneralPak[10581][Text18]"] = "Re-enchant~the~Evil~Array.~It`s~the~only~way.~Would~you~like~to~take~this~critical~task~of~enchanting~the~array?",
    ["STR_ID_GeneralPak[10581][Text19]"] = "~Find~Monk~Misery~at~the~Evil~Array,~and~he`ll~tell~you~what~to~do.",
    ["STR_ID_GeneralPak[10581][Text20]"] = "Those~Ghost~Reaver~are~invisible~in~the~evil~gas.~I~heard~that~Mr.~Mirror~has~a~skill~to~reveal~those~demons.~Maybe,~you~can~ask~him~for~help.",
