    -- PaksGhost [10579]
    ["STR_ID_PaksGhost[10579][Text1]"] = "No...~No...~You`re~not~the~Trojan~I`m~looking~for.~It`s~been~300~years,~however,~I~still~can`t~find~that~chosen~man.",
    ["STR_ID_PaksGhost[10579][Text2]"] = "@STR_COMMON[274]",
    ["STR_ID_PaksGhost[10579][Text3]"] = "Hey,~YOU!~You`re~the~chosen~man.~You~know,~I`ve~been~here~300~years,~waiting~for~you!",
    ["STR_ID_PaksGhost[10579][Text4]"] = "@STR_COMMON[275]",
    ["STR_ID_PaksGhost[10579][Text5]"] = "@STR_COMMON[276]",
    ["STR_ID_PaksGhost[10579][Text6]"] = "Finally...~the~Solar~Blade~is~back!~With~its~power,~you~can~travel~back~in~time~for~300~years.~Remember~to~find~me~at~that~time!",
    ["STR_ID_PaksGhost[10579][Text7]"] = "~See~you~in~Twin~City.",
    ["STR_ID_PaksGhost[10579][Text8]"] = "@STR_COMMON[274]",
    ["STR_ID_PaksGhost[10579][Text9]"] = "It`s~a~long~story,~but~I`ll~make~it~short.~300~years~ago,~I~was~ordered~to~defend~against~the~invasion~of~the~Flame~Devastator.",
    ["STR_ID_PaksGhost[10579][Text10]"] = "~Before~the~battle,~I~made~a~secret~plan,~however,~the~Flame~Devastator~has~already~known~it~and~trapped~my~army.",
    ["STR_ID_PaksGhost[10579][Text11]"] = "~No~one~survived.~Over~a~night,~Twin~City~was~ruined~and~thousands~of~civilians~were~killed.",
    ["STR_ID_PaksGhost[10579][Text12]"] = "There~must~be~a~traitor~in~my~army!~How~can~I~rest~in~peace~without~digging~him~out?~So,~my~soul~lived~on~my~Solar~Blade`s~Remain,",
    ["STR_ID_PaksGhost[10579][Text13]"] = "~waiting~for~a~chance.~Look,~you`re~the~chance!~Are~you~willing~to~travel~back~in~time~for~300~years,~and~root~out~this~cowardly~traitor?",
    ["STR_ID_PaksGhost[10579][Text14]"] = "~So,~we~can~stop~the~Flame~Devastator~and~avoid~the~massacre~of~Twin~City.",
    ["STR_ID_PaksGhost[10579][Text15]"] = "@STR_COMMON[274]",
    ["STR_ID_PaksGhost[10579][Text16]"] = "Finally...~the~Solar~Blade~is~back!~With~its~power,~you~can~travel~back~in~time~for~300~years.~Remember~to~find~me~at~that~time!",
    ["STR_ID_PaksGhost[10579][Text17]"] = "~See~you~in~Twin~City.",
    ["STR_ID_PaksGhost[10579][Text18]"] = "@STR_COMMON[274]",
    ["STR_ID_PaksGhost[10579][Text19]"] = "You~need~to~collect~27~Solar~Scraps,~first.~With~them,~I~can`t~reforge~the~Solar~Blade.",
    ["STR_ID_PaksGhost[10579][Text20]"] = "You~need~to~collect~27~Solar~Scraps,~first.~With~them,~I~can`t~reforge~the~Solar~Blade.",
    ["STR_ID_PaksGhost[10579][Text21]"] = "You~can~probably~get~the~Solar~Scraps~from~Super~Mok.~She~holds~the~secret~of~solar~power.~Well,~you~need~to~provide~the~materials~for~making~the~Solar~Scraps.",
    ["STR_ID_PaksGhost[10579][Text22]"] = "~Since~the~job~is~quite~exhausted,~she~can~only~make~1~Solar~Scrap~in~a~day.",
    ["STR_ID_PaksGhost[10579][Text23]"] = "@STR_COMMON[274]",
    ["STR_ID_PaksGhost[10579][Text24]"] = "The~Solar~Blade`s~Remain~is~already~in~your~inventory.",
    ["STR_ID_PaksGhost[10579][Text25]"] = "This~is~the~Solar~Blade`s~Remain.~Keep~it~well!",
    ["STR_ID_PaksGhost[10579][Text26]"] = "Your~inventory~is~full.~Make~some~room,~first.",
    ["STR_ID_PaksGhost[10579][Text27]"] = "Sorry,~the~Flame~Devastator~is~much~fiercer~than~you~imagined.~You~should~be~at~least~Level~120~to~challenge.",
