    -- CloudSweeper [19128]
    ["STR_ID_CloudSweeper[19128][Text1]"] = "Every day, when you team up with at least one friend, and conquer the Tower of Mystery at any challenge mode,",
    ["STR_ID_CloudSweeper[19128][Text2]"] = "@STR_COMMON[33]",
    ["STR_ID_CloudSweeper[19128][Text3]"] = "Ah, you`ve completed the challenge nicely. Here is a reward for you.",
    ["STR_ID_CloudSweeper[19128][Text4]"] = "To claim a reward from me, you need to team up with your friends and conquere the Tower of Mystery.",
    ["STR_ID_CloudSweeper[19128][Text5]"] = "Look, you`ve already claimed a reward from me. No more for today.",

