    ["STR_ID_CSElitePkManager[19424][Text4]"] = "Contestants will be fighting in 3 level divisions. The higher division, the better the prize. Prizes are granted via mail.",
    ["STR_ID_CSElitePkManager[19424][Text5]"] = "Champion: 7-day 1% Blessed Astral Phoenix, 30-day champion title and halo,",
    ["STR_ID_CSElitePkManager[19424][Text6]"] = "Champion: 30-day champion halo and 3,000 <tip color=0xfff05050 desc=Swap#it#for#nice#rewards#with#the#CS#Elite#PK#Manager.>Elite PK Point Coupons</tip>.",
    ["STR_ID_CSElitePkManager[19424][Text7]"] = "Champion: 2,000 <tip color=0xfff05050 desc=Swap#it#for#nice#rewards#with#the#CS#Elite#PK#Manager.>Elite PK Point Coupons</tip>.",
    ["STR_ID_CSElitePkManager[19424][Text8]"] = "Please sign up between 19:55 and 19:59 every Thursday night for the Cross Elite PK Tournament.",

