    -- Ghost_MoMo [4506]
    ["STR_ID_Ghost_MoMo[4506][Text1]"] = "Here is way better than home. I could play all day here. Mom and Dad would only scold me for anything I do.",
    ["STR_ID_Ghost_MoMo[4506][Text2]"] = "You will find some clues near Fete Pillar (162,217).",
    ["STR_ID_Ghost_MoMo[4506][Option1]"] = "You~should~go~home.",

    -- Dark_MoMo [4526]
    ["STR_ID_Dark_MoMo[4526][Text1]"] = "I love here! It`s fun! I`m not going home!",
    ["STR_ID_Dark_MoMo[4526][Text2]"] = "It`s dark. I`m scared.",
    ["STR_ID_Dark_MoMo[4526][Text3]"] = "You still don`t get the Bezoar. Go get it.",
    ["STR_ID_Dark_MoMo[4526][Text4]"] = "I love here! It`s fun! I`m not going home!",
    ["STR_ID_Dark_MoMo[4526][Text5]"] = "Thanks for bringing me home! My mother must prepare a reward for you! Go talk to her!",
    ["STR_ID_Dark_MoMo[4526][Option1]"] = "Your~mom~is~worried~about~you!",
    ["STR_ID_Dark_MoMo[4526][Option2]"] = "Take~the~Bezoar.",
    ["STR_ID_Dark_MoMo[4526][Option3]"] = "@STR_COMMON[91]",
    ["STR_ID_Dark_MoMo[4526][Option4]"] = "Go~with~me.",
    ["STR_ID_Dark_MoMo[4526][Option5]"] = "@STR_COMMON[56]",

    -- JerkWang [4504]
    ["STR_ID_JerkWang[4504][Text1]"] = "Impossible is nothing. Nothing is impossible.",
    ["STR_ID_JerkWang[4504][Text2]"] = "It was all my fault. I should have kept an eye on him. I was reading. Mo Mo was out playing alone.",
    ["STR_ID_JerkWang[4504][Text3]"] = "Some one saw him disappear in the east of the city all of a sudden. Will you find him for me?",
    ["STR_ID_JerkWang[4504][Text4]"] = "It`s all my fault... I should have been more careful...",
    ["STR_ID_JerkWang[4504][Text5]"] = "Mo Mo was seen in these three spots: (269,215), (298,205) and (357,304). Please search there.",
    ["STR_ID_JerkWang[4504][Text6]"] = "@STR_COMMON[33]",
    ["STR_ID_JerkWang[4504][Text7]"] = "Ah... now I remember, maybe you should visit Taoist Shine (245,258). He lives in Twin City",
    ["STR_ID_JerkWang[4504][Text8]"] = "Taoist Shine (245,258) must know why. Please pay him a visit.",
    ["STR_ID_JerkWang[4504][Option1]"] = "Where`s~Mo~Mo?",
    ["STR_ID_JerkWang[4504][Option2]"] = "I`m~trying~find~Mo~Mo.",
    ["STR_ID_JerkWang[4504][Option3]"] = "Do~you~have~any~solution?",
    ["STR_ID_JerkWang[4504][Option4]"] = "Just~do~it.",
    ["STR_ID_JerkWang[4504][Option5]"] = "Then~what?",
    ["STR_ID_JerkWang[4504][Option6]"] = "@STR_COMMON[181]",
    ["STR_ID_JerkWang[4504][Option7]"] = "What~shall~we~do?",
    ["STR_ID_JerkWang[4504][Option8]"] = "@STR_COMMON[91]",
    ["STR_ID_JerkWang[4504][Option9]"] = "@STR_COMMON[37]",
    ["STR_ID_JerkWang[4504][Option10]"] = "I`ll~visit~him.",
    ["STR_ID_JerkWang[4504][Option11]"] = "Good~idea!",

    -- AuntZhang [4503]
    ["STR_ID_AuntZhang[4503][Text1]"] = "Childern are happiest when celebrating festivals...They are running around everywhere. But sometimes they might get lost...",
    ["STR_ID_AuntZhang[4503][Text2]"] = "Thank you for saving my son. Please take this as my token of my gratitude.",
    ["STR_ID_AuntZhang[4503][Text3]"] = "I really appreciate your help! Please go claim your reward from Taskmaster Chang!",
    ["STR_ID_AuntZhang[4503][Text4]"] = "Mo Mo is lost! Please, you have to help me!",
    ["STR_ID_AuntZhang[4503][Text5]"] = "Have you seen my son on your way here? His name is Mo Mo. He is a cute little boy, about this height... I couldn`t find him.",
    ["STR_ID_AuntZhang[4503][Option1]"] = "@STR_COMMON[376]",
    ["STR_ID_AuntZhang[4503][Option2]"] = "You~should~be~careful.",
    ["STR_ID_AuntZhang[4503][Option3]"] = "Your~son~is~back!",
    ["STR_ID_AuntZhang[4503][Option4]"] = "I`ve~found~your~son!",
    ["STR_ID_AuntZhang[4503][Option5]"] = "I~agree.",
    ["STR_ID_AuntZhang[4503][Option6]"] = "@STR_COMMON[371]",
    ["STR_ID_AuntZhang[4503][Option7]"] = "@STR_COMMON[56]",
    ["STR_ID_AuntZhang[4503][Option8]"] = "How~did~it~happen?",
    ["STR_ID_AuntZhang[4503][Option9]"] = "I`ll~give~him~a~visit.",

    -- DoctorKnowitAll [4701]
    ["STR_ID_DoctorKnowitAll[4701][Text1]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text2]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text3]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text4]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text5]"] = "You must pay me a meteor and then I will make the Peel Pill for Xiao. The pill is made by Bird Blood, Ginseng Grease and Hawk Claw. But they are toxic and there are",
    ["STR_ID_DoctorKnowitAll[4701][Text6]"] = "~side-effects when people take this...I can`t guarantee its effects either...you know...Anything is possible...",
    ["STR_ID_DoctorKnowitAll[4701][Text7]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text8]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text9]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text10]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text11]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text12]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text13]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text14]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text15]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text16]"] = "@STR_COMMON[384]",
    ["STR_ID_DoctorKnowitAll[4701][Text17]"] = "According to my records, only Golden Rocs may suffer from this kind of syndrome...",
    ["STR_ID_DoctorKnowitAll[4701][Text18]"] = "@STR_COMMON[385]",
    ["STR_ID_DoctorKnowitAll[4701][Text19]"] = "Calm down, let me check first ... According to my records, only Golden Rocs may suffer from this kind of syndrome...",
    ["STR_ID_DoctorKnowitAll[4701][Text20]"] = "@STR_COMMON[385]",
    ["STR_ID_DoctorKnowitAll[4701][Text21]"] = "I heard that General Yue, the great hero, was the incarnation of a Golden Roc. Is it possible that Poor Xiao is his descendent?",
    ["STR_ID_DoctorKnowitAll[4701][Text22]"] = "Calm down, let me check first ... According to my records, only Golden Rocs may suffer from this kind of syndrome...",
    ["STR_ID_DoctorKnowitAll[4701][Text23]"] = "@STR_COMMON[385]",
    ["STR_ID_DoctorKnowitAll[4701][Text24]"] = "You`ve already got a Peel Pill!",
    ["STR_ID_DoctorKnowitAll[4701][Text25]"] = "You lost it? You should have been more careful! Well, I will give you a new one.",
    ["STR_ID_DoctorKnowitAll[4701][Text26]"] = "@STR_COMMON[386]",
    ["STR_ID_DoctorKnowitAll[4701][Text27]"] = "@STR_COMMON[387]",
    ["STR_ID_DoctorKnowitAll[4701][Text28]"] = "@STR_COMMON[387]",
    ["STR_ID_DoctorKnowitAll[4701][Text29]"] = "@STR_COMMON[386]",
    ["STR_ID_DoctorKnowitAll[4701][Text30]"] = "Only when you kill 2 of them within 1 minute, will you get a Hawk Claw. So have you got 5 Hawk Claws?",
    ["STR_ID_DoctorKnowitAll[4701][Text31]"] = "@STR_COMMON[387]",
    ["STR_ID_DoctorKnowitAll[4701][Text32]"] = "@STR_COMMON[386]",
    ["STR_ID_DoctorKnowitAll[4701][Text33]"] = "I need 5 Hawk Claws. Otherwise I`m not able to make the Peel Pill.",
    ["STR_ID_DoctorKnowitAll[4701][Text34]"] = "Good, now I need 5 Hawk Claws. You`re going to hunt the Level 93 Hawks. Only when you kill 2 of them within 1 minute, will you get a Hawk Claw.",
    ["STR_ID_DoctorKnowitAll[4701][Text35]"] = "Bitter Ginseng is made by Haw King`s Gallbladderr. You`ve got it?",
    ["STR_ID_DoctorKnowitAll[4701][Text36]"] = "Good, now I need 5 Hawk Claws. You`re going to hunt the Level 93 Hawks. Only when you kill 2 of them within 1 minute, will you get a Hawk Claw.",
    ["STR_ID_DoctorKnowitAll[4701][Text37]"] = "I need 1 Bitter Ginseng to make Ginseng Grease. Please take the Gallbladder drops from Haw King on Bird Island (451,676)",
    ["STR_ID_DoctorKnowitAll[4701][Text38]"] = "You lost the map? It`s okay. I`ll give you another.",
    ["STR_ID_DoctorKnowitAll[4701][Text39]"] = "Your inventory is full! Hurry to make some room!",
    ["STR_ID_DoctorKnowitAll[4701][Text40]"] = "It`s made by Haw King`s Gallbladderr. Here`s a map, telling you where the Bitter Ginseng could be found. Use the Gallbladderr at the spots",
    ["STR_ID_DoctorKnowitAll[4701][Text41]"] = "~and you may find a Bitter Ginseng.",
    ["STR_ID_DoctorKnowitAll[4701][Text42]"] = "I need 10 samples of Bird Blood. Have you got them?",
    ["STR_ID_DoctorKnowitAll[4701][Text43]"] = "Good job. Now, you are going to find a Bitter Ginseng.",
    ["STR_ID_DoctorKnowitAll[4701][Text44]"] = "Hey, there! You don`t have enough Bird Blood. I need 10. You got it?",
    ["STR_ID_DoctorKnowitAll[4701][Text45]"] = "It`s made by Haw King`s Gallbladderr. Here`s a map, telling you where the Bitter Ginseng could be found. Use the Gallbladderr at the spots",
    ["STR_ID_DoctorKnowitAll[4701][Text46]"] = "~and you may find a Bitter Ginseng.",
    ["STR_ID_DoctorKnowitAll[4701][Text47]"] = "You`ve got a map, already!",
    ["STR_ID_DoctorKnowitAll[4701][Text48]"] = "Your inventory is full! Hurry to make some room!",
    ["STR_ID_DoctorKnowitAll[4701][Text49]"] = "I need a Meteor. Do you have?",
    ["STR_ID_DoctorKnowitAll[4701][Text50]"] = "You`re kindhearted, huh?",
    ["STR_ID_DoctorKnowitAll[4701][Text51]"] = "I need a Meteor. Do not bother me again unless you have got one.",
    ["STR_ID_DoctorKnowitAll[4701][Text52]"] = "Well, first of all, you`re going to gather 10 samples of Bird Blood. You can get them from the Birdmen and Level 88 Birdmen.",
    ["STR_ID_DoctorKnowitAll[4701][Text53]"] = "I know the antidote for Poor Xiao`s weird disease!",
    ["STR_ID_DoctorKnowitAll[4701][Text54]"] = "You must pay me a meteor and then I will make the Peel Pill for Xiao. The pill is made by Bird Blood, Ginseng Grease and Hawk Claw. But they are toxic and there are",
    ["STR_ID_DoctorKnowitAll[4701][Text55]"] = "~side-effects when people take this...I can`t guarantee its effects either...you know...Anything is possible...",
    ["STR_ID_DoctorKnowitAll[4701][Text56]"] = "You must pay me a meteor and then I will make the Peel Pill for Xiao. The pill is made by Bird Blood, Ginseng Grease and Hawk Claws. But they are toxic and there are",
