    -- PoorXiao [4700]
    ["STR_ID_PoorXiao[4700][Text1]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text2]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text3]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text4]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text5]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text6]"] = "The pill is toxic? And the Meteor, I don`t have any...",
    ["STR_ID_PoorXiao[4700][Text7]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text8]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text9]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text10]"] = "Thank you, for bringing me the pill and helping me know my identity! Please go claim your reward from Taskmaster Chang.",
    ["STR_ID_PoorXiao[4700][Text11]"] = "@STR_COMMON[394]",
    ["STR_ID_PoorXiao[4700][Text12]"] = "My parents passed away when I was young, leaving only a Jade Pendant. The words inscribed on it say, `Serve thy country`.",
    ["STR_ID_PoorXiao[4700][Text13]"] = "~Now I know I am one of the descendents of General Yue, the great hero.",
    ["STR_ID_PoorXiao[4700][Text14]"] = "Since I`ve known my identity, I`ll work hard and never disappoint my ancestors. Thank you! Please go claim your reward from Taskmaster Chang.",
    ["STR_ID_PoorXiao[4700][Text15]"] = "You`ve got the pill? Great!",
    ["STR_ID_PoorXiao[4700][Text16]"] = "@STR_COMMON[395]",
    ["STR_ID_PoorXiao[4700][Text17]"] = "Are you kidding me? Please, go find Doctor Know-it-All right away.",
    ["STR_ID_PoorXiao[4700][Text18]"] = "@STR_COMMON[395]",
    ["STR_ID_PoorXiao[4700][Text19]"] = "@STR_COMMON[395]",
    ["STR_ID_PoorXiao[4700][Text20]"] = "I will try it, no matter what might happen. But I still need a Meteor to complete the prescription of the Peel Pill.",
    ["STR_ID_PoorXiao[4700][Text21]"] = "The pill is toxic? And the Meteor, I don`t have any...",
    ["STR_ID_PoorXiao[4700][Text22]"] = "Alright, I`m willing to have a try. But you see, I`m poor and it`s impossible for me to afford a Meteor...",
    ["STR_ID_PoorXiao[4700][Text23]"] = "@STR_COMMON[396]",
    ["STR_ID_PoorXiao[4700][Text24]"] = "@STR_COMMON[396]",
    ["STR_ID_PoorXiao[4700][Text25]"] = "Hello! Please don`t get scared by me...These ugly feathers grew all over my body out of a blue. I learnt that",
    ["STR_ID_PoorXiao[4700][Text26]"] = "~Doctor Know-it-All on Bird Island (701,595) has a special prescription for this. Will you give me a hand?",
    ["STR_ID_PoorXiao[4700][Text27]"] = "@STR_COMMON[396]",
    ["STR_ID_PoorXiao[4700][Option1]"] = "You~knew~General~Yue?",
    ["STR_ID_PoorXiao[4700][Option2]"] = "@STR_COMMON[217]",
    ["STR_ID_PoorXiao[4700][Option3]"] = "I`ve~got~the~pill.",
    ["STR_ID_PoorXiao[4700][Option4]"] = "@STR_COMMON[59]",
    ["STR_ID_PoorXiao[4700][Option5]"] = "@STR_COMMON[376]",
    ["STR_ID_PoorXiao[4700][Option6]"] = "Enjoy~yourself.",
    ["STR_ID_PoorXiao[4700][Option7]"] = "Let~me~tell~you~something.",
    ["STR_ID_PoorXiao[4700][Option8]"] = "@STR_COMMON[57]",
    ["STR_ID_PoorXiao[4700][Option9]"] = "I`ll~help~you.",
    ["STR_ID_PoorXiao[4700][Option10]"] = "@STR_COMMON[380]",
    ["STR_ID_PoorXiao[4700][Option11]"] = "What`s~your~opinion?",
    ["STR_ID_PoorXiao[4700][Option12]"] = "Have~you~made~your~choice?",
    ["STR_ID_PoorXiao[4700][Option13]"] = "@STR_COMMON[64]",
    ["STR_ID_PoorXiao[4700][Option14]"] = "Here`s~the~antidote.",
    ["STR_ID_PoorXiao[4700][Option15]"] = "I`m~busy.",
    ["STR_ID_PoorXiao[4700][Option16]"] = "I`m~leaving.",
    ["STR_ID_PoorXiao[4700][Option17]"] = "@STR_COMMON[56]",
    ["STR_ID_PoorXiao[4700][Option18]"] = "Later.",
    ["STR_ID_PoorXiao[4700][Option19]"] = "I`m~leaving.",
    ["STR_ID_PoorXiao[4700][Option20]"] = "That`s~true.",
    ["STR_ID_PoorXiao[4700][Option21]"] = "@STR_COMMON[371]",
    ["STR_ID_PoorXiao[4700][Option22]"] = "Hurry~to~take~it!",
    ["STR_ID_PoorXiao[4700][Option23]"] = "@STR_COMMON[397]",
    ["STR_ID_PoorXiao[4700][Option24]"] = "@STR_COMMON[57]",
    ["STR_ID_PoorXiao[4700][Option25]"] = "@STR_COMMON[397]",
    ["STR_ID_PoorXiao[4700][Option26]"] = "@STR_COMMON[397]",
    ["STR_ID_PoorXiao[4700][Option27]"] = "Don`t~worry.",
    ["STR_ID_PoorXiao[4700][Option28]"] = "What`s~your~opinion?",
    ["STR_ID_PoorXiao[4700][Option29]"] = "@STR_COMMON[398]",
    ["STR_ID_PoorXiao[4700][Option30]"] = "Sorry~about~it.",
    ["STR_ID_PoorXiao[4700][Option31]"] = "@STR_COMMON[91]",
    ["STR_ID_PoorXiao[4700][Option32]"] = "@STR_COMMON[91]",
    ["STR_ID_PoorXiao[4700][Option33]"] = "Of~course~I~will.",
    ["STR_ID_PoorXiao[4700][Option34]"] = "Sorry,~not~now.",
    ["STR_ID_PoorXiao[4700][Option35]"] = "@STR_COMMON[91]",

    -- TaskmasterChang [8796]
    ["STR_ID_TaskmasterChang[8796][Text1]"] = "@STR_COMMON[399]",
