    ["STR_ID_TaskmasterChang[8796][Text4]"] = "Sorry, but you`ll need to reach at least Level 120 to accept the quest.",
    ["STR_ID_TaskmasterChang[8796][Text5]"] = "The~Tempest~Wings~have~appeared!~It`s~an~intelligent~talisman~to~boost~your~strength,~as~well~as~a~dazzling~symbol~of~nobility,",
    ["STR_ID_TaskmasterChang[8796][Text6]"] = "~making~you~stand~out~in~a~second.~Wanna~be~the~Champion~of~champions?~Go~and~find~Mr.~Wonder~(212,196)~in~Phoenix~Castle",
    ["STR_ID_TaskmasterChang[8796][Text7]"] = "~to~forge~a~pair~of~Tempest~Wings.",
    ["STR_ID_TaskmasterChang[8796][Text8]"] = "You`ve~already~completed~the~quest,~haven`t~you?",
