    -- GeneralZhuGe [8437]
    ["STR_ID_GeneralZhuGe[8437][Text1]"] = "It was a nice village in Desert, but turned into a refuge overnight after the sandstorm. Well, at least the villagers haven`t lost their hearts.",
    ["STR_ID_GeneralZhuGe[8437][Text2]"] = "You`ve got the Antidote? Hurry to deliver it to Spring Soldier Zhao.",
    ["STR_ID_GeneralZhuGe[8437][Text3]"] = "All clues are indicating the Level Blade Ghosts! I need you to kill them to get the Antidote and take it to Spring Soldier Zhao.",
    ["STR_ID_GeneralZhuGe[8437][Text4]"] = "All clues are indicating the Level Blade Ghosts! I need you to kill them to get the Antidote and take it to Spring Soldier Zhao.",
    ["STR_ID_GeneralZhuGe[8437][Text5]"] = "Villagers are poisoned by the spring! I`ll figure that out!",
    ["STR_ID_GeneralZhuGe[8437][Text6]"] = "Thank you! The villagers will be able to go out and fetch water, again.",
    ["STR_ID_GeneralZhuGe[8437][Text7]"] = "What are you waiting for? Go kill 50 Rock Monsters!",
    ["STR_ID_GeneralZhuGe[8437][Text8]"] = "Oh-oh! The Rock Monsters on the west of the camp blocked the way to the Moon Spring! That`s the most important water source in the desert.",
    ["STR_ID_GeneralZhuGe[8437][Text9]"] = "Great! That may be enough to keep them from being so bold.",
    ["STR_ID_GeneralZhuGe[8437][Text10]"] = "A horde of Hill Monsters L73 are going to attack the camp.",
    ["STR_ID_GeneralZhuGe[8437][Text11]"] = "It`s reported that some Hill Monsters L73 are going to attack the camp, tonight!",
    ["STR_ID_GeneralZhuGe[8437][Text12]"] = "@STR_COMMON[33]",
    ["STR_ID_GeneralZhuGe[8437][Text13]"] = "Well done! Please take these gifts, as your rewards.",
    ["STR_ID_GeneralZhuGe[8437][Text14]"] = "We should do something to save the camp. Go kill 50 of the Hill Monsters, and cut down their power!",
    ["STR_ID_GeneralZhuGe[8437][Text15]"] = "More and more Hill Monsters are gathering outside the camp! It`s really dangerous.",
    ["STR_ID_GeneralZhuGe[8437][Text16]"] = "@STR_COMMON[33]",
    ["STR_ID_GeneralZhuGe[8437][Text17]"] = "Really? You`ve cleared the way? Good job!",
    ["STR_ID_GeneralZhuGe[8437][Text18]"] = "You came at the right time! A refugee camp in Desert was surrounded by a group of Hill Monsters.",
    ["STR_ID_GeneralZhuGe[8437][Text19]"] = "Please make 3 mores space in your inventory.",
    ["STR_ID_GeneralZhuGe[8437][Option1]"] = "Speedy~Rescue.",
    ["STR_ID_GeneralZhuGe[8437][Option2]"] = "Poisonous~Water~2.",
    ["STR_ID_GeneralZhuGe[8437][Option3]"] = "Poisonous~Water~3.",
    ["STR_ID_GeneralZhuGe[8437][Option4]"] = "Hill~Monster`s~Threat.",
    ["STR_ID_GeneralZhuGe[8437][Option5]"] = "Kill~the~Hill~Monsters~(L73).",
    ["STR_ID_GeneralZhuGe[8437][Option6]"] = "Retrieve~the~Water~Source.",
    ["STR_ID_GeneralZhuGe[8437][Option7]"] = "Thank you for the letter.",
    ["STR_ID_GeneralZhuGe[8437][Option8]"] = "They`ll~get~better.",

    -- IronsmithLi [8438]
    ["STR_ID_IronsmithLi[8438][Text1]"] = "Hey, I`m an ironsmith. What can I do for you? You need any smithing done, by chance?",
    ["STR_ID_IronsmithLi[8438][Text2]"] = "So is it a Thunder Stone? I`ll reveal the secret.",
    ["STR_ID_IronsmithLi[8438][Text3]"] = "@STR_COMMON[421]",
    ["STR_ID_IronsmithLi[8438][Text4]"] = "Yes! That`s my grindstone! Thank you!",
    ["STR_ID_IronsmithLi[8438][Text5]"] = "My grindstone was stolen by the Rock Monsters! It`s useless for them but to me, it`s important. Please, go retrieve it!",
    ["STR_ID_IronsmithLi[8438][Text6]"] = "@STR_COMMON[33]",
    ["STR_ID_IronsmithLi[8438][Text7]"] = "Great! I`ll go report to the General. Here`s your reward, by the way.",
    ["STR_ID_IronsmithLi[8438][Text8]"] = "This is my Newly Made Hammer. I need you to test it.",
    ["STR_ID_IronsmithLi[8438][Text9]"] = "Haha, this is my Newly Made Hammer. I need you to test it out.",
    ["STR_ID_IronsmithLi[8438][Text10]"] = "@STR_COMMON[33]",
    ["STR_ID_IronsmithLi[8438][Text11]"] = "See? These hammers are great! Thank you very much!",
    ["STR_ID_IronsmithLi[8438][Text12]"] = "With the help of Hill Monster`s hammers, I`ll make better weapons.",
    ["STR_ID_IronsmithLi[8438][Text13]"] = "To be frank, I`m quite interested in the Hill Monster`s hammer. Could you collect some for me?",
    ["STR_ID_IronsmithLi[8438][Text14]"] = "@STR_COMMON[363]",
    ["STR_ID_IronsmithLi[8438][Option1]"] = "Stolen~Grindstone.",
    ["STR_ID_IronsmithLi[8438][Option2]"] = "Ironsmith`s~Request.",
    ["STR_ID_IronsmithLi[8438][Option3]"] = "The~New~Weapon.",
    ["STR_ID_IronsmithLi[8438][Option4]"] = "Stolen~Grindstone.",
    ["STR_ID_IronsmithLi[8438][Option5]"] = "@STR_COMMON[14]",

    -- ViceGeneralDong [8439]
    ["STR_ID_ViceGeneralDong[8439][Text1]"] = "I`m the Vice General, you can call me Dong. Watching the refugee camp is my duty.",
    ["STR_ID_ViceGeneralDong[8439][Text2]"] = "Good idea! I`ll ask the villagers to plant more of the cactus. Thanks for your advice!",
    ["STR_ID_ViceGeneralDong[8439][Text3]"] = "@STR_COMMON[416]",
    ["STR_ID_ViceGeneralDong[8439][Text4]"] = "I`m the Vice General, you can call me Dong. Watching the refugee camp is my duty.",
    ["STR_ID_ViceGeneralDong[8439][Text5]"] = "The Rock Monsters are known for carrying fine Slabstones. You can collect some, and use them to build a wall around the pool in 4 directions.",
    ["STR_ID_ViceGeneralDong[8439][Text6]"] = "The sand is swallowing the water pool. We need to collect some slabstones to build a sand-proof wall around the pool.",
    ["STR_ID_ViceGeneralDong[8439][Text7]"] = "You`ve built the wall! You`ve been such a big help!",
    ["STR_ID_ViceGeneralDong[8439][Text8]"] = "@STR_COMMON[363]",
    ["STR_ID_ViceGeneralDong[8439][Text9]"] = "You`re going to turn to the Rock Monsters for the Slabstones. After that, go build a wall around the water pool in 4 directions.",
    ["STR_ID_ViceGeneralDong[8439][Text10]"] = "@STR_COMMON[364]",
    ["STR_ID_ViceGeneralDong[8439][Text11]"] = "Really? You`ve gathered enough Heavy Axes? Thank you!",
    ["STR_ID_ViceGeneralDong[8439][Text12]"] = "Emergency! Our armory is running low on weapons and the supply lines are cut off!",
    ["STR_ID_ViceGeneralDong[8439][Text13]"] = "@STR_COMMON[33]",
    ["STR_ID_ViceGeneralDong[8439][Text14]"] = "You made it? Were they scared? Haha!",
    ["STR_ID_ViceGeneralDong[8439][Text15]"] = "We have a plan. We need a brave man, like you, to go deep into the Hill Monster`s lair and set a fire. That should smoke them out!",
    ["STR_ID_ViceGeneralDong[8439][Text16]"] = "@STR_COMMON[425]",
    ["STR_ID_ViceGeneralDong[8439][Text17]"] = "@STR_COMMON[33]",
    ["STR_ID_ViceGeneralDong[8439][Option1]"] = "The~Cactus~5.",
    ["STR_ID_ViceGeneralDong[8439][Option2]"] = "Go~Deep~into~the~Lair.",
    ["STR_ID_ViceGeneralDong[8439][Option3]"] = "The~Supply~Line.",
    ["STR_ID_ViceGeneralDong[8439][Option4]"] = "The~Sand-proof~Wall.",
    ["STR_ID_ViceGeneralDong[8439][Option5]"] = "@STR_COMMON[14]",

    -- KeYulun [8434]
    ["STR_ID_KeYulun[8434][Text1]"] = "This desert is often called the throat of the Silk Road. Merchants from all over the world came here, as well as evildoers.",
    ["STR_ID_KeYulun[8434][Text2]"] = "Great! We`re going home! Thanks a million!",
    ["STR_ID_KeYulun[8434][Text3]"] = "My followers and I are planning to go home right away. But the problem is, the path is blocked by the bloody monsters, again!",
    ["STR_ID_KeYulun[8434][Text4]"] = "@STR_COMMON[416]",
    ["STR_ID_KeYulun[8434][Text5]"] = "Thanks for what you`ve done for us! Please accept these rewards!",
    ["STR_ID_KeYulun[8434][Text6]"] = "While going through the desert, we were hit by a sand storm and my follower was kidnapped by the Level 68 Sand Monsters.",
    ["STR_ID_KeYulun[8434][Text7]"] = "While going through the desert, we were hit by a sand storm and my follower was kidnapped by the Level 68 Sand Monsters.",
    ["STR_ID_KeYulun[8434][Text8]"] = "@STR_COMMON[416]",
    ["STR_ID_KeYulun[8434][Text9]"] = "Tell me how to thank you enough! You saved my life!",
    ["STR_ID_KeYulun[8434][Text10]"] = "Thank God you came! I ran into a sand storm on my way here, and was badly injured. Can you bring me a Ginseng, please?",
    ["STR_ID_KeYulun[8434][Option1]"] = "Clear~the~Path.",
    ["STR_ID_KeYulun[8434][Option2]"] = "Ginseng~Delivery.",
    ["STR_ID_KeYulun[8434][Option3]"] = "Save~the~Company.",
    ["STR_ID_KeYulun[8434][Option4]"] = "@STR_COMMON[14]",

