    ["STR_ID_SkillEraser[15988][Text508]"] = "@STR_COMMON[463]",
    ["STR_ID_SkillEraser[15988][Text509]"] = "@STR_COMMON[464]",
    ["STR_ID_SkillEraser[15988][Text510]"] = "Are you sure you want to pay 10.000 CPs to add 1 blessed attribute to the Gourd?",
