    ["STR_ID_SkillEraser[15988][Text519]"] = "@STR_COMMON[464]",
    ["STR_ID_SkillEraser[15988][Text520]"] = "Are you sure you want to pay 10.000 CPs to add 1 blessed attribute to the Heaven Fan?",
