    -- FrozenGrottoGeneral [6144]
    ["STR_ID_FrozenGrottoGeneral[6144][Text1]"] = "You can get the monster hunter quest from the TC Captain now! It`s a great place for you to level up. Here is a steed to",
    ["STR_ID_FrozenGrottoGeneral[6144][Text2]"] = "@STR_COMMON[428]",
    ["STR_ID_FrozenGrottoGeneral[6144][Text3]"] = "You are able to take the quest from the PC Captain now! You can level up more quickly there. Here is a steed to take you there!",
    ["STR_ID_FrozenGrottoGeneral[6144][Text4]"] = "You`d better take the quests from the AC Captain. It`s the right place for you to level up. Here is a steed to take you",
    ["STR_ID_FrozenGrottoGeneral[6144][Text5]"] = "~there!",
    ["STR_ID_FrozenGrottoGeneral[6144][Text6]"] = "You are powerful enough to take the quests from the DC Captain now! Here is a steed to take you there!",
    ["STR_ID_FrozenGrottoGeneral[6144][Text7]"] = "You are powerful now, and you are able to take the quests from the BI Captain! He is in need of your help! Here is a steed to",
    ["STR_ID_FrozenGrottoGeneral[6144][Text8]"] = "@STR_COMMON[428]",
    ["STR_ID_FrozenGrottoGeneral[6144][Text9]"] = "You are strong enough to kill the monsters in Mystic Castle. Why not take a quest from MC Captain to level up quickly? Here",
    ["STR_ID_FrozenGrottoGeneral[6144][Text10]"] = "~is a steed to take you there.",
    ["STR_ID_FrozenGrottoGeneral[6144][Text11]"] = "Cloud Saint in Market (291,224) is looking for the heroes to help him exterminate the monsters. If you can finish the quest,",
    ["STR_ID_FrozenGrottoGeneral[6144][Text12]"] = "~you will receive 5 EXP Balls as rewards!",
