    ["STR_ID_InnerPowerNpc[18786][Text341]"] = "@STR_COMMON[527]",
    ["STR_ID_InnerPowerNpc[18786][Text342]"] = "@STR_COMMON[528]",
    ["STR_ID_InnerPowerNpc[18786][Text343]"] = "@STR_COMMON[529]",
    ["STR_ID_InnerPowerNpc[18786][Text344]"] = "Wow, you`re so lucky to enter the Heaven Treasury! Let me introduce you the rules here.",
    ["STR_ID_InnerPowerNpc[18786][Text345]"] = "You can open one Mystery Chest for free, once in a day. For the other chests, you need to use CPs.",
    ["STR_ID_InnerPowerNpc[18786][Text346]"] = "1st Time: 60 minutes of EXP, 10 Study Points, 1 Chi Token and 1 Heaven Key Scrap;\n",
    ["STR_ID_InnerPowerNpc[18786][Text347]"] = "1st Time Extra Reward: 1 Talent point;\n",
    ["STR_ID_InnerPowerNpc[18786][Text348]"] = "I`m here to deliver seeds, and I can also teleport you back to Twin City.",
    ["STR_ID_InnerPowerNpc[18786][Text349]"] = "I don`t have any Magnolia Seeds. You`ll need to wait until tomorrow!",
    -- {0}=DbItem.Name
    ["STR_ID_InnerPowerNpc[18786][Text350]"] = "{0} \n",
    -- {0}=client.Player.DailyMagnoliaChance.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text351]"] = "You`ve already changed [{0}] times.\n",
    ["STR_ID_InnerPowerNpc[18786][Text352]"] = "@STR_COMMON[403]",
    ["STR_ID_InnerPowerNpc[18786][Text353]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text354]"] = "Sorry, but you don`t have enough StudyPoints.",
    ["STR_ID_InnerPowerNpc[18786][Text355]"] = "@STR_COMMON[403]",
    ["STR_ID_InnerPowerNpc[18786][Text356]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text357]"] = "I`ll tell you a secret! Did you know that different seeds will bring you different rewards?",
    ["STR_ID_InnerPowerNpc[18786][Text358]"] = "If your Normal Magnolia Seed becomes a flower, you`ll receive 60 minutes of EXP, 10 Study Points and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text359]"] = "If your Refined Magnolia Seed becomes a flower, you`ll have the chance to receive 90 minutes of EXP, 20 Study Points, 1 Chi Token, and more!",
    ["STR_ID_InnerPowerNpc[18786][Text360]"] = "If your Unique Magnolia Seed becomes a flower, you`ll have the chance to receive 120 minutes of EXP, 50 Study Points, 1 Chi Token, and more!",
    ["STR_ID_InnerPowerNpc[18786][Text361]"] = "If your Elite Magnolia Seed becomes a flower, you`ll have the chance to receive 180 minutes of EXP, 100 Study Points, 1 Chi Token, and more!",
    ["STR_ID_InnerPowerNpc[18786][Text362]"] = "If your Super Magnolia Seed becomes a flower, you`ll have the chance to receive 300 minutes of EXP, 300 Study Points, 1 Chi Token, and more!",
    ["STR_ID_InnerPowerNpc[18786][Text363]"] = "Several days ago, a group of bandits appeared in the Desert, and we failed to defeat them. Many of our soldiers were killed.",
    ["STR_ID_InnerPowerNpc[18786][Text364]"] = "You`ve helped us a lot, already! You`d better have a rest. If you want, you can come back tomorrow!",
    ["STR_ID_InnerPowerNpc[18786][Text365]"] = "You have released the souls of some dead soldiers, right? Just a few? Well, thanks for your help! I`ve got something to give you,",
    ["STR_ID_InnerPowerNpc[18786][Text366]"] = "Eh? Could it be there are still decent men in the world? It`s very kind of you to offer! If you can find 8 Soldier`s Remains and release their souls,",
    ["STR_ID_InnerPowerNpc[18786][Text367]"] = "@STR_COMMON[403]",
    ["STR_ID_InnerPowerNpc[18786][Text368]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text369]"] = "You`ve~accepted~the~quest:~Release~the~Souls.~Find~at~least~8~Soldier`s~Remains~in~the~Desert!",
    ["STR_ID_InnerPowerNpc[18786][Text370]"] = "You`ve collect enough spirits. Do you want to claim 120 minutes of EXP, 7 hours of Blessing, 30 Study Points and a Chi Token, now?",
    -- {0}=GetDailySpiritBeadKills(client), {1}=client.Player.DailySpiritBeadCount
    ["STR_ID_InnerPowerNpc[18786][Text371]"] = "@STR_COMMON[530]",
    ["STR_ID_InnerPowerNpc[18786][Text372]"] = "This is a Normal Spirit Bead. Once fully charged, you`ll receive 120 minutes of EXP, 7 hours of Blessing, 30 Study Points and a Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text373]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text374]"] = "You`ve collect enough spirits. Do you want to claim 180 minutes of EXP, 10 hours of Blessing, 40 Study Points and 1 Chi Token, now?",
    -- {0}=GetDailySpiritBeadKills(client), {1}=client.Player.DailySpiritBeadCount
    ["STR_ID_InnerPowerNpc[18786][Text375]"] = "@STR_COMMON[530]",
    ["STR_ID_InnerPowerNpc[18786][Text376]"] = "This is a Normal Spirit Bead. Once fully charged, you`ll receive 180 minutes of EXP, 10 hours of Blessing, 40 Study Points and 1 Chi Token",
    ["STR_ID_InnerPowerNpc[18786][Text377]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text378]"] = "You`ve collect enough spirits. Do you want to claim 240 minutes of EXP, 15 hours of Blessing, 50 Study Points and 1 Chi Token, now?",
    -- {0}=GetDailySpiritBeadKills(client), {1}=client.Player.DailySpiritBeadCount
    ["STR_ID_InnerPowerNpc[18786][Text379]"] = "@STR_COMMON[530]",
    ["STR_ID_InnerPowerNpc[18786][Text380]"] = "This is a Normal Spirit Bead. Once fully charged, you`ll receive 240 minutes of EXP, 15 hours of Blessing, 50 Study Points and 1 Chi Token",
    ["STR_ID_InnerPowerNpc[18786][Text381]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text382]"] = "You`ve collect enough spirits. Do you want to claim 300 minutes of EXP, 24 hours of Blessing, 80 Study Points and 1 Chi Token, now?",
    -- {0}=GetDailySpiritBeadKills(client), {1}=client.Player.DailySpiritBeadCount
    ["STR_ID_InnerPowerNpc[18786][Text383]"] = "@STR_COMMON[530]",
    ["STR_ID_InnerPowerNpc[18786][Text384]"] = "This is a Normal Spirit Bead. Once fully charged, you`ll receive 300 minutes of EXP, 24 hours of Blessing, 80 Study Points and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text385]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text386]"] = "You`ve collect enough spirits. Do you want to claim 360 minutes of EXP, 48 hours of Blessing, 100 Study Points and 1 Chi Token, now?",
    -- {0}=GetDailySpiritBeadKills(client), {1}=client.Player.DailySpiritBeadCount
    ["STR_ID_InnerPowerNpc[18786][Text387]"] = "@STR_COMMON[530]",
    ["STR_ID_InnerPowerNpc[18786][Text388]"] = "This is a Normal Spirit Bead. Once fully charged, you`ll receive 360 minutes of EXP, 48 hours of Blessing, 100 Study Points and 1 Chi Token.",
    ["STR_ID_InnerPowerNpc[18786][Text389]"] = "@STR_COMMON[367]",
    ["STR_ID_InnerPowerNpc[18786][Text390]"] = "Every day when you successfully challenged the Tower of Mystery, you can claim",
    ["STR_ID_InnerPowerNpc[18786][Text391]"] = "@STR_COMMON[416]",
    ["STR_ID_InnerPowerNpc[18786][Text392]"] = "You haven`t completed the challenge of the Tower of Mystery, and you can`t claim the rewards, otherwise you wold like to pay 1500 CPs or a Mystery Amulet.",
    ["STR_ID_InnerPowerNpc[18786][Text393]"] = "@STR_COMMON[416]",
    ["STR_ID_InnerPowerNpc[18786][Text394]"] = "You don`t have enough CPs to directly get the rewards.",
    ["STR_ID_InnerPowerNpc[18786][Text395]"] = "@STR_COMMON[416]",
    ["STR_ID_InnerPowerNpc[18786][Text396]"] = "You don`t have Mystery amulet to directly get the rewards.",
    ["STR_ID_InnerPowerNpc[18786][Text397]"] = "If you have 3 Exorcism Tokens, you can exchange for an Exorcism Pack. And if you have 9 tokens, you can get a",
    ["STR_ID_InnerPowerNpc[18786][Text398]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text399]"] = "Sorry, but you don`t have 3 Exorcism Tokens.",
    ["STR_ID_InnerPowerNpc[18786][Text400]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text401]"] = "Sorry, but you don`t have 9 Exorcism Tokens.",
    ["STR_ID_InnerPowerNpc[18786][Text402]"] = "Welcome, my friend. Are you sure you want to release the Thrilling Spook now, or would you rather return to the TwinCity",
    ["STR_ID_InnerPowerNpc[18786][Text403]"] = "I just want to be sure. Shall I release the Thrilling Spook, now?",
    ["STR_ID_InnerPowerNpc[18786][Text404]"] = "Sorry,~you~cannot~release the Thrilling~Spook ~before~your~Level~is~70.~Please~train~harder.",
