    ["STR_ID_InnerPowerNpc[18786][Text486]"] = "@STR_COMMON[552]",
    ["STR_ID_InnerPowerNpc[18786][Text487]"] = "@STR_COMMON[553]",
    ["STR_ID_InnerPowerNpc[18786][Text488]"] = "@STR_COMMON[554]",
    ["STR_ID_InnerPowerNpc[18786][Text489]"] = "@STR_COMMON[555]",
    ["STR_ID_InnerPowerNpc[18786][Text490]"] = "@STR_COMMON[556]",
    ["STR_ID_InnerPowerNpc[18786][Text491]"] = "@STR_COMMON[557]",
    ["STR_ID_InnerPowerNpc[18786][Text492]"] = "@STR_COMMON[558]",
    ["STR_ID_InnerPowerNpc[18786][Text493]"] = "@STR_COMMON[559]",
    ["STR_ID_InnerPowerNpc[18786][Text494]"] = "@STR_COMMON[560]",
    ["STR_ID_InnerPowerNpc[18786][Text495]"] = "@STR_COMMON[561]",
