    ["STR_ID_InnerPowerNpc[18786][Text1169]"] = "@STR_COMMON[632]",
    ["STR_ID_InnerPowerNpc[18786][Text1170]"] = "@STR_COMMON[33]",
    ["STR_ID_InnerPowerNpc[18786][Text1171]"] = "You`ve got the Military Letter. Go give it to the TC Vice Captain!",
    ["STR_ID_InnerPowerNpc[18786][Text1172]"] = "This is the letter you want. Take it. By the way, don`t forget about our wonderful storage services!",
    ["STR_ID_InnerPowerNpc[18786][Text1173]"] = "@STR_COMMON[632]",
    ["STR_ID_InnerPowerNpc[18786][Text1174]"] = "In exchange of a fee of 500gold, I will teleport you back to the guild war map. Don't bother me if you are poor.",
    ["STR_ID_InnerPowerNpc[18786][Text1175]"] = "@STR_COMMON[633]",
    ["STR_ID_InnerPowerNpc[18786][Text1176]"] = "Are~you~heading~for~the~next~teleporter?~It~is~free~for~our~members,~and~1,000~silver~for~others.",
