    ["STR_ID_InnerPowerNpc[18786][Text1488]"] = "Good day, my friend, I`m the TC Captain, I`m in charge of the public security around",
    ["STR_ID_InnerPowerNpc[18786][Text1489]"] = "@STR_COMMON[675]",
    ["STR_ID_InnerPowerNpc[18786][Text1490]"] = "Defeat 10 Pheasants outside Twin City. You are doing for this for people of Twin City!",
    ["STR_ID_InnerPowerNpc[18786][Text1491]"] = "I have some jobs for you to do here! The Pheasants outside Twin City are becoming more",
    ["STR_ID_InnerPowerNpc[18786][Text1492]"] = "@STR_COMMON[675]",
    ["STR_ID_InnerPowerNpc[18786][Text1493]"] = "There is a long way to go! You need some professional guidance to grow stronger! Find the NPC of your class",
    ["STR_ID_InnerPowerNpc[18786][Text1494]"] = "@STR_COMMON[666]",
