    ["STR_ID_InnerPowerNpc[18786][Text1502]"] = "@STR_COMMON[674]",
    ["STR_ID_InnerPowerNpc[18786][Text1503]"] = "@STR_COMMON[666]",
    ["STR_ID_InnerPowerNpc[18786][Text1504]"] = "You have finished killing all the monsters for today. Do you want to claim your prize?",
    ["STR_ID_InnerPowerNpc[18786][Text1505]"] = "You have killed the amount required for this stage. Do you want to advance?",
    ["STR_ID_InnerPowerNpc[18786][Text1506]"] = "You didn't finish killing the amount of monsters for your current stage. Are you giving up?",
    ["STR_ID_InnerPowerNpc[18786][Text1507]"] = "@STR_COMMON[666]",
    ["STR_ID_InnerPowerNpc[18786][Text1508]"] = "You are too weak to take quests from me. Go and find the MC Captain.",
    ["STR_ID_InnerPowerNpc[18786][Text1509]"] = "Stay calm and listem, the Demons are taking over the control of ",
    ["STR_ID_InnerPowerNpc[18786][Text1510]"] = "the world. My family is the only one that can make a contract with ",
    ["STR_ID_InnerPowerNpc[18786][Text1511]"] = "the humans to purify the world from the devils. I can give you two ",
    ["STR_ID_InnerPowerNpc[18786][Text1512]"] = "expballs as reward for doing it. But you can do it once one time per ",
    ["STR_ID_InnerPowerNpc[18786][Text1513]"] = "day, what will you do?",
    -- {0}=string.Concat("Now go and kill ", Database.InfoDemonExterminators.StageKills[stage], " ", Database.InfoDemonExterminators.QuestName[client.DemonExterminator.QuestTyp][stage], " then come back.")
