    ["STR_ID_InnerPowerNpc[18786][Text1534]"] = "Sorry, you don`t have 10 meteors.",
    ["STR_ID_InnerPowerNpc[18786][Text1535]"] = "Pay 100,000 Silver and give me 5 EXP Balls, I can pack them into an EXP Ball Gift Box for you!",
