    -- {0}=SpellID.ToString()
    ["STR_ID_InnerPowerNpc[18786][Text1634]"] = "@STR_COMMON[692]",
    ["STR_ID_InnerPowerNpc[18786][Text1635]"] = "You don`t have 100,000 silver. You are unable to learn the Spook skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1636]"] = "After the mount is equipped, you can right click the (Riding) button or drag the button into the shortcut column to ride",
    -- {0}=SpellID.ToString()
