    ["STR_ID_InnerPowerNpc[18786][Text1638]"] = "@STR_COMMON[692]",
    ["STR_ID_InnerPowerNpc[18786][Text1639]"] = "You don`t have 50,000 silver. You are unable to learn the Riding skill.",
    ["STR_ID_InnerPowerNpc[18786][Text1640]"] = "Sorry, but you are not a Taoist.",
