    ["STR_ID_InnerPowerNpc[18786][Text2036]"] = "@STR_COMMON[692]",
    ["STR_ID_InnerPowerNpc[18786][Text2037]"] = "The Chaser branch is famous for its ability to control wind and outstanding ranged attacks.",
