    ["STR_ID_InnerPowerNpc[18786][Text2090]"] = "@STR_COMMON[742]",
    ["STR_ID_InnerPowerNpc[18786][Text2091]"] = "(You`re currently on the [RangedChaser] branch. Each Windwalker can switch his/her branch once every 30 days, free of charge.)",
    ["STR_ID_InnerPowerNpc[18786][Text2092]"] = "@STR_COMMON[741]",
