    ["STR_ID_InnerPowerNpc[18786][Text2101]"] = "@STR_COMMON[748]",
    ["STR_ID_InnerPowerNpc[18786][Text2102]"] = "@STR_COMMON[747]",
    ["STR_ID_InnerPowerNpc[18786][Text2103]"] = "@STR_COMMON[749]",
