    ["STR_ID_InnerPowerNpc[18786][Text2106]"] = "@STR_COMMON[750]",
    ["STR_ID_InnerPowerNpc[18786][Text2107]"] = "@STR_COMMON[749]",
    ["STR_ID_InnerPowerNpc[18786][Text2108]"] = "Okay, I`ve changed your branch to [RangedStomper].",
    ["STR_ID_InnerPowerNpc[18786][Text2109]"] = "@STR_COMMON[750]",
    ["STR_ID_InnerPowerNpc[18786][Text2110]"] = "Trojans do not share their secrets of battle with others. I shall not teach you.",
