    ["STR_ID_InnerPowerNpc[18786][Text2135]"] = "The XP skills for Trojans are Accuracy, Cyclone and Golem. Accuracy can triple your hit rate; Cyclone can increase your speed; By using the Golem skill, you can transform",
    ["STR_ID_InnerPowerNpc[18786][Text2136]"] = "Fierce as hurricane, Fatal Cross will crash all blocking the way. While the Mortal Strike holds a devastated power that can cause terrifying damage.",
    ["STR_ID_InnerPowerNpc[18786][Text2137]"] = "You`ve learned MortalStrike!",
    ["STR_ID_InnerPowerNpc[18786][Text2138]"] = "You~successfully~acquired~the~skill,~[Mortal~Strike].~Equip~2~Trojan`s~Epic~Weapons~to~cast.~While~attacking,~the~caster~has~a~chance~to~cause~severe~damage~on~human~targets,",
    ["STR_ID_InnerPowerNpc[18786][Text2139]"] = "~and~more~violent~to~monsters,~within~a~certain~range.",
    ["STR_ID_InnerPowerNpc[18786][Text2140]"] = "@STR_COMMON[694]",
    ["STR_ID_InnerPowerNpc[18786][Text2141]"] = "You need to equip a Trojan`s Epic Weapon to learn [MortalStrike].",
    ["STR_ID_InnerPowerNpc[18786][Text2142]"] = "You`ve~already~acquired~this~skill.",
    ["STR_ID_InnerPowerNpc[18786][Text2143]"] = "You~successfully~acquired~the~skill,~[Fatal~Cross].~This~active~skill~is~for~Trojan`s~Epic~Weapon~only.",
    ["STR_ID_InnerPowerNpc[18786][Text2144]"] = "~Equip~2~Epic~Weapons~and~throw~the~Cross~Saber~in~target~direction,~inflicting~damage~on~all~the~targets",
    ["STR_ID_InnerPowerNpc[18786][Text2145]"] = "~within~2~paces~along~its~attack~path.~Cost:~25~Stamina.",
    ["STR_ID_InnerPowerNpc[18786][Text2146]"] = "@STR_COMMON[694]",
    ["STR_ID_InnerPowerNpc[18786][Text2147]"] = "You need to equip a Trojan`s Epic Weapon to learn [Fatal Cross].",
