    ["STR_ID_InnerPowerNpc[18786][Text2370]"] = "@STR_COMMON[704]",
    ["STR_ID_InnerPowerNpc[18786][Text2371]"] = "If you want to learn the Scurvy Bomb, you`ll need to be a pure Pirate, who`ve been a Pirate for 3 straight lives. You can talk to the Rebirth Master in the Market to have the Reincarnation.",
    -- {0}=SpellID.ToString()
