    ["STR_ID_ThiefChen[4437][Text4]"] = "@STR_COMMON[488]",
    ["STR_ID_ThiefChen[4437][Text5]"] = "@STR_COMMON[487]",
    ["STR_ID_ThiefChen[4437][Text6]"] = "You said you came from Twin City and were looking for Thief Chen? What`s the problem?",
    ["STR_ID_ThiefChen[4437][Text7]"] = "Well, I`m still going to need you to prove yourself. Go kill 5 Bandits, first!",
    ["STR_ID_ThiefChen[4437][Text8]"] = "Fine. I guess I can trust you, after all.",
    ["STR_ID_ThiefChen[4437][Text9]"] = "@STR_COMMON[488]",
    ["STR_ID_ThiefChen[4437][Text10]"] = "Why are you still here? Deliver the letter to Wong, right away!",
    ["STR_ID_ThiefChen[4437][Text11]"] = "@STR_COMMON[403]",
    ["STR_ID_ThiefChen[4437][Text12]"] = "Hey, friend! Check your bag. The letter is right there!",
    ["STR_ID_ThiefChen[4437][Option1]"] = "Are~you~the~Connector?",
    ["STR_ID_ThiefChen[4437][Option2]"] = "Hi!~Connector!",
    ["STR_ID_ThiefChen[4437][Option3]"] = "I~came~for~Thief~Wong.",
    ["STR_ID_ThiefChen[4437][Option4]"] = "@STR_COMMON[409]",
    ["STR_ID_ThiefChen[4437][Option5]"] = "Thanks~for~reminding.",
    ["STR_ID_ThiefChen[4437][Option6]"] = "Thief~Wong~sent~me~here.",
    ["STR_ID_ThiefChen[4437][Option7]"] = "Piece~of~cake.",
    ["STR_ID_ThiefChen[4437][Option8]"] = "@STR_COMMON[420]",
    ["STR_ID_ThiefChen[4437][Option9]"] = "@STR_COMMON[409]",
    ["STR_ID_ThiefChen[4437][Option10]"] = "I~lost~the~letter.",
    ["STR_ID_ThiefChen[4437][Option11]"] = "@STR_COMMON[37]",
    ["STR_ID_ThiefChen[4437][Option12]"] = "@STR_COMMON[145]",

