    ["STR_ID_ThiefWong[4436][Text1]"] = "@STR_COMMON[489]",
    ["STR_ID_ThiefWong[4436][Text2]"] = "@STR_COMMON[489]",
    ["STR_ID_ThiefWong[4436][Text3]"] = "@STR_COMMON[489]",
    ["STR_ID_ThiefWong[4436][Text4]"] = "@STR_COMMON[489]",
