    ["STR_ID_ThiefWong[4436][Text7]"] = "@STR_COMMON[403]",
    ["STR_ID_ThiefWong[4436][Text8]"] = "@STR_COMMON[490]",
    ["STR_ID_ThiefWong[4436][Text9]"] = "The problem is, I was wounded by the guards as I escaped. Can you take a message to my connector, Thief Chen?",
    ["STR_ID_ThiefWong[4436][Text10]"] = "Thank you for the letter!",
    ["STR_ID_ThiefWong[4436][Text11]"] = "Here`s your reward. Thank you again!",
    ["STR_ID_ThiefWong[4436][Option1]"] = "Here`s~a~letter~for~you!",
    ["STR_ID_ThiefWong[4436][Option2]"] = "Yeah!~Count~me~in!",
