    -- ZhaoJian [4465]
    ["STR_ID_ZhaoJian[4465][Text1]"] = "@STR_COMMON[491]",
    ["STR_ID_ZhaoJian[4465][Text2]"] = "@STR_COMMON[491]",
    ["STR_ID_ZhaoJian[4465][Text3]"] = "@STR_COMMON[491]",
    ["STR_ID_ZhaoJian[4465][Text4]"] = "I usually charge a fortune for this work, but as you`re going to rid us of Cloud the Lustful... I suppose I can make an exception.",
    ["STR_ID_ZhaoJian[4465][Option1]"] = "I~need~your~help.",

    -- VeteranHong [4464]
    ["STR_ID_VeteranHong[4464][Text1]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text2]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text3]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text4]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text5]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text6]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text7]"] = "Yes! I`m in trouble now, and I could use your help. Someone has stolen my Spun Gold Armor. Were this found out by the Emperor,",
    ["STR_ID_VeteranHong[4464][Text8]"] = "Yes! I guess it was those bandits who stole my armor. You should find them and try to recover any clues you can. Feel free to use force.",
    ["STR_ID_VeteranHong[4464][Text9]"] = "Rumor has it that those bandits who roam outside the city have something to do with this. Go find them and see what they know!",
    ["STR_ID_VeteranHong[4464][Text10]"] = "This is an invitation to the Treasure Appraisal Meeting. Now I`m positive the Spun Gold Armor was stolen by Cloud the Lustful!",
    ["STR_ID_VeteranHong[4464][Text11]"] = "@STR_COMMON[492]",
    ["STR_ID_VeteranHong[4464][Text12]"] = "Cloud the Lustful is the head of those bandits. They are a motley crew... Notorious and capable of committing",
    ["STR_ID_VeteranHong[4464][Text13]"] = "Thank you! I thought I would never regain my precious armor. Please, let me repay you for your heroic feat.",
    ["STR_ID_VeteranHong[4464][Text14]"] = "He usually shows up around a small altar in the southwest of Phoenix Castle. He is a randy old man, and actually quite disgusting.",
    ["STR_ID_VeteranHong[4464][Text15]"] = "@STR_COMMON[403]",
    ["STR_ID_VeteranHong[4464][Text16]"] = "Are you kidding me? You`ve already got the offering!",
    ["STR_ID_VeteranHong[4464][Text17]"] = "Thank you for retrieving my Spun Gold Armor. Now you can speak with Taskmaster Chang, to claim your reward.",
    ["STR_ID_VeteranHong[4464][Option1]"] = "@STR_COMMON[376]",
    ["STR_ID_VeteranHong[4464][Option2]"] = "Anything~I~can~help~you~with?",
    ["STR_ID_VeteranHong[4464][Option3]"] = "@STR_COMMON[799]",
    ["STR_ID_VeteranHong[4464][Option4]"] = "I`ve~got~something~for~you..",
    ["STR_ID_VeteranHong[4464][Option5]"] = "@STR_COMMON[65]",
    ["STR_ID_VeteranHong[4464][Option6]"] = "@STR_COMMON[408]",
    ["STR_ID_VeteranHong[4464][Option7]"] = "Dirty~thief!",
    ["STR_ID_VeteranHong[4464][Option8]"] = "@STR_COMMON[57]",
    ["STR_ID_VeteranHong[4464][Option9]"] = "@STR_COMMON[799]",
    ["STR_ID_VeteranHong[4464][Option10]"] = "@STR_COMMON[75]",
    ["STR_ID_VeteranHong[4464][Option11]"] = "@STR_COMMON[371]",
    ["STR_ID_VeteranHong[4464][Option12]"] = "Gimme~some~offerings.",
    ["STR_ID_VeteranHong[4464][Option13]"] = "@STR_COMMON[37]",
    ["STR_ID_VeteranHong[4464][Option14]"] = "@STR_COMMON[369]",
    ["STR_ID_VeteranHong[4464][Option15]"] = "@STR_COMMON[74]",

    -- ScholarWu [4482]
    ["STR_ID_ScholarWu[4482][Text1]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text2]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text3]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text4]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text5]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text6]"] = "@STR_COMMON[493]",
    ["STR_ID_ScholarWu[4482][Text7]"] = "Hats off to your valor! You saved my life! Please accept this, with my thanks.",
    ["STR_ID_ScholarWu[4482][Text8]"] = "Thank you! You saved me! Now go claim your reward from Taskmaster Chang!",
    ["STR_ID_ScholarWu[4482][Text9]"] = "Yes. But sigh... I still haven`t gotten over it...",
    ["STR_ID_ScholarWu[4482][Text10]"] = "Thank you. I heard there is a rat called the Fire Rat L38 outside the castle... Its eye and meat could be used to make a powerful",
    ["STR_ID_ScholarWu[4482][Text11]"] = "Well, you are so generous... thank you. The recipe for the Azure Pill belongs to Pharmacist Mu Mu (182,241). Please go there",
    ["STR_ID_ScholarWu[4482][Option1]"] = "Did~you~go~to~see~a~doctor?",
    ["STR_ID_ScholarWu[4482][Option2]"] = "Maybe~I~can~help?",
    ["STR_ID_ScholarWu[4482][Option3]"] = "@STR_COMMON[800]",
    ["STR_ID_ScholarWu[4482][Option4]"] = "@STR_COMMON[800]",
    ["STR_ID_ScholarWu[4482][Option5]"] = "@STR_COMMON[801]",
    ["STR_ID_ScholarWu[4482][Option6]"] = "@STR_COMMON[801]",
    ["STR_ID_ScholarWu[4482][Option7]"] = "@STR_COMMON[78]",
    ["STR_ID_ScholarWu[4482][Option8]"] = "@STR_COMMON[254]",
    ["STR_ID_ScholarWu[4482][Option9]"] = "@STR_COMMON[378]",
    ["STR_ID_ScholarWu[4482][Option10]"] = "Sure!",
    ["STR_ID_ScholarWu[4482][Option11]"] = "I`m~off~right~now.",

    -- BianQing [4484]
