    ["STR_ID_BianQing[4484][Text2]"] = "@STR_COMMON[494]",
    ["STR_ID_BianQing[4484][Text3]"] = "@STR_COMMON[494]",
    ["STR_ID_BianQing[4484][Text4]"] = "Yes, sure. So my old friend Mu Mu sent you here? Let me see... you need to collect 1 Ratling Eye and 3 Ratling Meat, yourself,",
