    ["STR_ID_PharmacistMuMu[4483][Text10]"] = "Finally, the Azure Pill is done. Hurry up, bring it to Scholar Wu.",
    ["STR_ID_PharmacistMuMu[4483][Text11]"] = "@STR_COMMON[33]",
    ["STR_ID_PharmacistMuMu[4483][Text12]"] = "@STR_COMMON[33]",
    ["STR_ID_PharmacistMuMu[4483][Text13]"] = "Haha, the Azure Pill is done!",
    ["STR_ID_PharmacistMuMu[4483][Text14]"] = "Finally, the Azure Pill is done. Hurry up, bring it to Scholar Wu",
    ["STR_ID_PharmacistMuMu[4483][Text15]"] = "Don`t bother me, right now. Get some manners and be patient, OK?",
    ["STR_ID_PharmacistMuMu[4483][Text16]"] = "Oh, Scholar Wu`s disease... It`s difficult to cure. I`ll try my best, but I`ll need your help gathering things I need.",
    ["STR_ID_PharmacistMuMu[4483][Text17]"] = "@STR_COMMON[496]",
    ["STR_ID_PharmacistMuMu[4483][Text18]"] = "Excellent! All of the ingredients are here. Now leave me alone for a while so I can combine them into an Azure Pill.",
    ["STR_ID_PharmacistMuMu[4483][Text19]"] = "Now, bring me 1 Ratling Eye and 3 Ratling Meat. Make sure to get the 2 Herb Packs from Bian Qing (342,232).",
    ["STR_ID_PharmacistMuMu[4483][Text20]"] = "@STR_COMMON[497]",
