    ["STR_ID_PharmacistMuMu[4483][Option7]"] = "@STR_COMMON[390]",
    ["STR_ID_PharmacistMuMu[4483][Option8]"] = "Any~news~about~the~Azure~Pill?",
    ["STR_ID_PharmacistMuMu[4483][Option9]"] = "@STR_COMMON[75]",
    ["STR_ID_PharmacistMuMu[4483][Option10]"] = "@STR_COMMON[802]",
    ["STR_ID_PharmacistMuMu[4483][Option11]"] = "@STR_COMMON[37]",
