    -- FairyCloud [16050]
    ["STR_ID_FairyCloud[16050][Text1]"] = "Wow, you`re so lucky to enter the Heaven Treasury! Let me introduce you the rules here.",
    ["STR_ID_FairyCloud[16050][Text2]"] = "You can open one Mystery Chest for free, once in a day. For the other chests, you need to use CPs.",
    ["STR_ID_FairyCloud[16050][Text3]"] = "1st Time: 60 minutes of EXP, 10 Study Points, 1 Chi Token and 1 Heaven Key Scrap;\n",
    ["STR_ID_FairyCloud[16050][Text4]"] = "1st Time Extra Reward: 1 Talent point;\n",
    ["STR_ID_FairyCloud[16050][Option1]"] = "Learn~about~opening~chests.",
    ["STR_ID_FairyCloud[16050][Option2]"] = "@STR_COMMON[808]",
    ["STR_ID_FairyCloud[16050][Option3]"] = "What`s~for~Jiang~Hu~fighters.",
    ["STR_ID_FairyCloud[16050][Option4]"] = "@STR_COMMON[808]",

    -- MagnoliaEnvoy [9897]
    ["STR_ID_MagnoliaEnvoy[9897][Text1]"] = "I`m here to deliver seeds, and I can also teleport you back to Twin City.",
    ["STR_ID_MagnoliaEnvoy[9897][Text2]"] = "I don`t have any Magnolia Seeds. You`ll need to wait until tomorrow!",
    -- {0}=DbItem.Name
    ["STR_ID_MagnoliaEnvoy[9897][Text3]"] = "{0} \n",
    -- {0}=client.Player.DailyMagnoliaChance.ToString()
    ["STR_ID_MagnoliaEnvoy[9897][Text4]"] = "You`ve already changed [{0}] times.\n",
    ["STR_ID_MagnoliaEnvoy[9897][Text5]"] = "@STR_COMMON[403]",
    ["STR_ID_MagnoliaEnvoy[9897][Text6]"] = "@STR_COMMON[367]",
    ["STR_ID_MagnoliaEnvoy[9897][Text7]"] = "Sorry, but you don`t have enough StudyPoints.",
    ["STR_ID_MagnoliaEnvoy[9897][Text8]"] = "@STR_COMMON[403]",
    ["STR_ID_MagnoliaEnvoy[9897][Text9]"] = "@STR_COMMON[367]",
    ["STR_ID_MagnoliaEnvoy[9897][Text10]"] = "I`ll tell you a secret! Did you know that different seeds will bring you different rewards?",
    ["STR_ID_MagnoliaEnvoy[9897][Text11]"] = "If your Normal Magnolia Seed becomes a flower, you`ll receive 60 minutes of EXP, 10 Study Points and 1 Chi Token.",
    ["STR_ID_MagnoliaEnvoy[9897][Text12]"] = "If your Refined Magnolia Seed becomes a flower, you`ll have the chance to receive 90 minutes of EXP, 20 Study Points, 1 Chi Token, and more!",
    ["STR_ID_MagnoliaEnvoy[9897][Text13]"] = "If your Unique Magnolia Seed becomes a flower, you`ll have the chance to receive 120 minutes of EXP, 50 Study Points, 1 Chi Token, and more!",
    ["STR_ID_MagnoliaEnvoy[9897][Text14]"] = "If your Elite Magnolia Seed becomes a flower, you`ll have the chance to receive 180 minutes of EXP, 100 Study Points, 1 Chi Token, and more!",
    ["STR_ID_MagnoliaEnvoy[9897][Text15]"] = "If your Super Magnolia Seed becomes a flower, you`ll have the chance to receive 300 minutes of EXP, 300 Study Points, 1 Chi Token, and more!",
    ["STR_ID_MagnoliaEnvoy[9897][Option1]"] = "Claim~1~seed.",
    ["STR_ID_MagnoliaEnvoy[9897][Option2]"] = "Back~to~Twin~City.",
    ["STR_ID_MagnoliaEnvoy[9897][Option3]"] = "How~to~plant~them.",
    ["STR_ID_MagnoliaEnvoy[9897][Option4]"] = "@STR_COMMON[66]",
    ["STR_ID_MagnoliaEnvoy[9897][Option5]"] = "Claim~the~seed.",
    ["STR_ID_MagnoliaEnvoy[9897][Option6]"] = "Another~seed.~(50~CP)",
    ["STR_ID_MagnoliaEnvoy[9897][Option7]"] = "Another~seed.~(25~Study~Points)",
    ["STR_ID_MagnoliaEnvoy[9897][Option8]"] = "Buy~1~Super~seed.~(600~CPs)",
    ["STR_ID_MagnoliaEnvoy[9897][Option9]"] = "@STR_COMMON[79]",
    ["STR_ID_MagnoliaEnvoy[9897][Option10]"] = "@STR_COMMON[37]",
