    -- DesertGuardian [301]
    ["STR_ID_DesertGuardian[301][Text1]"] = "Several days ago, a group of bandits appeared in the Desert, and we failed to defeat them. Many of our soldiers were killed.",
    ["STR_ID_DesertGuardian[301][Text2]"] = "You`ve helped us a lot, already! You`d better have a rest. If you want, you can come back tomorrow!",
    ["STR_ID_DesertGuardian[301][Text3]"] = "You have released the souls of some dead soldiers, right? Just a few? Well, thanks for your help! I`ve got something to give you,",
    ["STR_ID_DesertGuardian[301][Text4]"] = "Eh? Could it be there are still decent men in the world? It`s very kind of you to offer! If you can find 8 Soldier`s Remains and release their souls,",
    ["STR_ID_DesertGuardian[301][Text5]"] = "@STR_COMMON[403]",
    ["STR_ID_DesertGuardian[301][Text6]"] = "@STR_COMMON[367]",
    ["STR_ID_DesertGuardian[301][Text7]"] = "You`ve~accepted~the~quest:~Release~the~Souls.~Find~at~least~8~Soldier`s~Remains~in~the~Desert!",
    ["STR_ID_DesertGuardian[301][Option1]"] = "Let~me~help~you.",
    ["STR_ID_DesertGuardian[301][Option2]"] = "@STR_COMMON[62]",
    ["STR_ID_DesertGuardian[301][Option3]"] = "@STR_COMMON[122]",
    ["STR_ID_DesertGuardian[301][Option4]"] = "Okay!~I`ll~go~now!",
    ["STR_ID_DesertGuardian[301][Option5]"] = "@STR_COMMON[37]",
    ["STR_ID_DesertGuardian[301][Option6]"] = "@STR_COMMON[47]",

