    -- GoodManLiu [9891]
    ["STR_ID_GoodManLiu[9891][Text1]"] = "Thanks for coming to the Ancestral Hall. They`re all the greatest Guild Leaders of all time!",
    ["STR_ID_GoodManLiu[9891][Text2]"] = "You just need to click on the incense burners in front of statues to worship Robin~, iEatBabies and ~*~PureHeart~*~. Each day, you only have one chance to worship one of them.",
    ["STR_ID_GoodManLiu[9891][Text3]"] = "xHolic is the leader of the 2nd Supreme Guild MakeMeFamous. Worshipping xHolic will bring you 60 minutes` EXP, 50 Study Points and 1 Chi Token.",
    ["STR_ID_GoodManLiu[9891][Text4]"] = "Robin~ is the leader of the 1st Supreme Guild SkillzDatKillz. Worshipping Robin~ will bring you 5 hours` Blessing, 60 minutes` EXP and 1 Chi Token.",
    ["STR_ID_GoodManLiu[9891][Text5]"] = "~*~PureHeart~*~ is the leader of the 3rd Supreme Guild Seven?hH??aven. Worshipping ~*~PureHeart~*~ will briing you 5 hours` Blessing, 50 Study Points and 1 Chi Token.",

