    -- IronTong [20499]
    ["STR_ID_IronTong[20499][Text1]"] = "<tip desc=In#the#battle#several#hundred#years#ago,#the#Five#Great#Masters#defeated#the#King#of#Evil#and#destroyed#his#Twisting#Hell#Array#",
    ["STR_ID_IronTong[20499][Text2]"] = "on#the#Dragon#Island.#After#that,#11#heroes#volunteered#to#station#on#the#island.#Iron#Tong#has#inherited#this#mission#more#than#ten#years.#",
    ["STR_ID_IronTong[20499][Text3]"] = "However,#the#hell#devils#broke#in#again.#To#get#out#of#this#crisis,#he#left#Dragon#Island#for#the#first#time.>Iron Tong</tip>: ",
    ["STR_ID_IronTong[20499][Text4]"] = "The Queen of Evil and her troop suddenly attacked the Dragon Island. Obviously, she came for the Twisting Hell Array.",
    ["STR_ID_IronTong[20499][Text5]"] = "~I`m afraid she has figured out how to reactivate that array. We`d better not to let it happen. For the sake of humans,",
    ["STR_ID_IronTong[20499][Text6]"] = "~please join us to defend the Dragon Island!",
    ["STR_ID_IronTong[20499][Option1]"] = "Send~me~to~Dragon~Island.",
    ["STR_ID_IronTong[20499][Option2]"] = "@STR_COMMON[125]",

