    -- CloudSaint [2000]
    ["STR_ID_CloudSaint[2000][Text1]"] = "@STR_COMMON[666]",
    ["STR_ID_CloudSaint[2000][Text2]"] = "You have finished killing all the monsters for today. Do you want to claim your prize?",
    ["STR_ID_CloudSaint[2000][Text3]"] = "You have killed the amount required for this stage. Do you want to advance?",
    ["STR_ID_CloudSaint[2000][Text4]"] = "You didn't finish killing the amount of monsters for your current stage. Are you giving up?",
    ["STR_ID_CloudSaint[2000][Text5]"] = "@STR_COMMON[666]",
    ["STR_ID_CloudSaint[2000][Text6]"] = "You are too weak to take quests from me. Go and find the MC Captain.",
    ["STR_ID_CloudSaint[2000][Text7]"] = "Stay calm and listem, the Demons are taking over the control of ",
    ["STR_ID_CloudSaint[2000][Text8]"] = "the world. My family is the only one that can make a contract with ",
    ["STR_ID_CloudSaint[2000][Text9]"] = "the humans to purify the world from the devils. I can give you two ",
    ["STR_ID_CloudSaint[2000][Text10]"] = "expballs as reward for doing it. But you can do it once one time per ",
    ["STR_ID_CloudSaint[2000][Text11]"] = "day, what will you do?",
