    ["STR_ID_CloudSaint[2000][Text14]"] = "Thank you, brave soldier, for accepting this quest. Kill {0} {1} and come back.",
    ["STR_ID_CloudSaint[2000][Text15]"] = "@STR_COMMON[674]",
    ["STR_ID_CloudSaint[2000][Text16]"] = "You need to buy that quest for 3.000 ConquerPoints?",
    ["STR_ID_CloudSaint[2000][Text17]"] = "Sorry you not have 98 ConquerPoints",
