    ["STR_ID_MarketLadyLuck[923][Text1]"] = "@STR_COMMON[687]",
    ["STR_ID_MarketLadyLuck[923][Text2]"] = "@STR_COMMON[687]",
    ["STR_ID_MarketLadyLuck[923][Text3]"] = "Each player can draw from the Lottery up to 10 times, each day. But if you are a VIP, you will have extra chances to play! Level 1 VIP: 10 extra chances. Level 2 VIP: 20 extra chances. Level 3 VIP: 30 extra chances. Level 4 VIP: 40 extra chances. Level 5 VIP: 50 extra chances. Level 6 VIP: 60 extra chances.",
