    -- PromotionWarrior [10001]
    ["STR_ID_PromotionWarrior[10001][Text1]"] = "Sorry, but you are not a Warrior.",
    ["STR_ID_PromotionWarrior[10001][Text2]"] = "@STR_COMMON[726]",
    ["STR_ID_PromotionWarrior[10001][Text3]"] = "@STR_COMMON[726]",
    ["STR_ID_PromotionWarrior[10001][Text4]"] = "To be a good Warrior, you must know your weapon, your armor be a 2nd skin, and use your shield to ward off your enemy! Remember, fortune favors the brave, and you must keep your head, even in the darkest hours. So, what can I do for you?",
    ["STR_ID_PromotionWarrior[10001][Text5]"] = "If you`re interested in the skills for Fist, I`m glad to give some guidance.",
