    ["STR_ID_PromotionWarrior[10001][Text66]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWarrior[10001][Text67]"] = "I`m proud that you made a mature decision! The warriors are adept in the use of weapons and shields for additional defense. Do you want to get promoted, now?",
    ["STR_ID_PromotionWarrior[10001][Text68]"] = "You`ve learned ways of the Warrior. Now, more weapons and armors are available for you, while new skills are at your disposal. Go test your power!",
    ["STR_ID_PromotionWarrior[10001][Option1]"] = "@STR_COMMON[868]",
    ["STR_ID_PromotionWarrior[10001][Option2]"] = "@STR_COMMON[868]",
