    -- PromotionWindWalker [19634]
    ["STR_ID_PromotionWindWalker[19634][Text1]"] = "You don`t look like a Windwalker. What`s the matter? If you were ever a Windwalker in either of the previous two lives, you can learn [Frost Gaze I] from me.",
    ["STR_ID_PromotionWindWalker[19634][Text2]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text3]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text4]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text5]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text6]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text7]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text8]"] = "Hey, FellowBrother! You`re back. Are you okay? No hurry, the Chief has sent me a letter and told me the things.",
    ["STR_ID_PromotionWindWalker[19634][Text9]"] = "Our Windwalker school was founded by Saint Wan on the principle of KINDNESS and JUSTICE. Once you decide to",
    ["STR_ID_PromotionWindWalker[19634][Text10]"] = "~join us as a Windwalker, you take the responsibility for the security of the country against alien invaders and devils.",
    ["STR_ID_PromotionWindWalker[19634][Text11]"] = "Our school and the devil force have been at daggers drawn for centuries, but I don`t really get their purposes for",
    ["STR_ID_PromotionWindWalker[19634][Text12]"] = "~attacking us and intruding the imperial mausoleum this time. Now that we`ve completed the service in the mausoleum,",
    ["STR_ID_PromotionWindWalker[19634][Text13]"] = "~we should return to society. FellowBrother, set off to investigate and avenge the deaths of our fellows!",
    ["STR_ID_PromotionWindWalker[19634][Text14]"] = "You`re such a talent and so promising. The Windwalker shool will amaze the world soon.",
    ["STR_ID_PromotionWindWalker[19634][Text15]"] = "~Remember, you can learn class skills and get promoted here to start your life. Would you like",
    ["STR_ID_PromotionWindWalker[19634][Text16]"] = "~to learn something about your class promotion and quests?",
    ["STR_ID_PromotionWindWalker[19634][Text17]"] = "Congratulations! You`ve graduated from the training quest. From now on, you are no longer a simple recruit, but a trained",
    ["STR_ID_PromotionWindWalker[19634][Text18]"] = "~soldier. You can sign up for your class quests with me when you`re Level 12, and get promoted at Level 15.",
    ["STR_ID_PromotionWindWalker[19634][Text19]"] = "~The world is filled with dangers, so be sure and take care of yourself!",
    ["STR_ID_PromotionWindWalker[19634][Text20]"] = "The TC Vice Captain (TwinCity 384,251) is now damned busy. Hey, if you can give him a hand,",
    ["STR_ID_PromotionWindWalker[19634][Text21]"] = "~he will remember you for the rest of his life. Hah, just kidding. Anyway, would you like to help him?",
    ["STR_ID_PromotionWindWalker[19634][Text22]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 15 to get promoted.",
    ["STR_ID_PromotionWindWalker[19634][Text23]"] = "@STR_COMMON[732]",
    ["STR_ID_PromotionWindWalker[19634][Text24]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 40 to get promoted.",
    ["STR_ID_PromotionWindWalker[19634][Text25]"] = "@STR_COMMON[571]",
    ["STR_ID_PromotionWindWalker[19634][Text26]"] = "@STR_COMMON[732]",
    ["STR_ID_PromotionWindWalker[19634][Text27]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 70 to get promoted.",
    ["STR_ID_PromotionWindWalker[19634][Text28]"] = "@STR_COMMON[698]",
    ["STR_ID_PromotionWindWalker[19634][Text29]"] = "@STR_COMMON[571]",
    ["STR_ID_PromotionWindWalker[19634][Text30]"] = "@STR_COMMON[733]",
    ["STR_ID_PromotionWindWalker[19634][Text31]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 100 to get promoted.",
    ["STR_ID_PromotionWindWalker[19634][Text32]"] = "@STR_COMMON[701]",
    ["STR_ID_PromotionWindWalker[19634][Text33]"] = "@STR_COMMON[403]",
    ["STR_ID_PromotionWindWalker[19634][Text34]"] = "@STR_COMMON[733]",
    ["STR_ID_PromotionWindWalker[19634][Text35]"] = "FellowBrother, you`re not qualified to be [WindwalkerGuard]. You should reach Level 110 to get promoted.",
    ["STR_ID_PromotionWindWalker[19634][Text36]"] = "@STR_COMMON[703]",
    ["STR_ID_PromotionWindWalker[19634][Text37]"] = "@STR_COMMON[403]",
    ["STR_ID_PromotionWindWalker[19634][Text38]"] = "@STR_COMMON[733]",
    ["STR_ID_PromotionWindWalker[19634][Text39]"] = "@STR_COMMON[704]",
    ["STR_ID_PromotionWindWalker[19634][Text40]"] = "Our Windwalker school is divided into two branches: Chaser and Stomper. Chaser focuses on",
    ["STR_ID_PromotionWindWalker[19634][Text41]"] = "~ranged combat, while Stomper excels in melee combat. I`m here representing the Chief to",
    ["STR_ID_PromotionWindWalker[19634][Text42]"] = "~impart distinctive skills to the Windwalkers.",
    ["STR_ID_PromotionWindWalker[19634][Text43]"] = "Frost Gaze is an exclusive rebirth skill for Windwalker. The heroes who got reborn to be Windwalker can learn Frost Gaze I. If both of your precious andd",
    ["STR_ID_PromotionWindWalker[19634][Text44]"] = "~current Class are Windwalker, you can learn Frost Gaze II. While for Windwalkers who were also a Windwalker in previous two lives, they can learn Frost Gaze III.",
    ["STR_ID_PromotionWindWalker[19634][Text45]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text46]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text47]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text48]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text49]"] = "@STR_COMMON[731]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text50]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text51]"] = "Omnipotence and Justice Chant are basic skills for Windwalker, which are available to both Chaser and Stomper learners. I`ll teach you if you want.",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text52]"] = "@STR_COMMON[734]",
