    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionWindWalker[19634][Text57]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionWindWalker[19634][Text58]"] = "The Chaser branch is famous for its ability to control wind and outstanding ranged attacks.",
