    -- PromotionTrojan [10022]
    ["STR_ID_PromotionTrojan[10022][Text1]"] = "Trojans do not share their secrets of battle with others. I shall not teach you.",
    ["STR_ID_PromotionTrojan[10022][Text2]"] = "@STR_COMMON[751]",
    ["STR_ID_PromotionTrojan[10022][Text3]"] = "@STR_COMMON[751]",
    ["STR_ID_PromotionTrojan[10022][Text4]"] = "@STR_COMMON[751]",
    ["STR_ID_PromotionTrojan[10022][Text5]"] = "Ah, you look promising. I bet `Trojan` will be a big name in a short time. Listen, you can learn class skills and",
    ["STR_ID_PromotionTrojan[10022][Text6]"] = "@STR_COMMON[695]",
    ["STR_ID_PromotionTrojan[10022][Text7]"] = "The Dragon Whirl is a Pure skill, which means that only players who`ve been a Trojan on their two past lives and their current life as well can learn it. Though you`ve been Reborn twice, You are not a Pure Trojan.",
    ["STR_ID_PromotionTrojan[10022][Text8]"] = "After your 2nd Rebirth, you still have to be Reincarnated and become a Pure Trojan, to be able to learn the Dragon Whirl skill.",
    ["STR_ID_PromotionTrojan[10022][Text9]"] = "You don'thave the combo ( Tro - Tro - Tro ) in your status.",
    ["STR_ID_PromotionTrojan[10022][Text10]"] = "@STR_COMMON[705]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionTrojan[10022][Text11]"] = "@STR_COMMON[691]",
    -- {0}=SpellID.ToString()
    ["STR_ID_PromotionTrojan[10022][Text12]"] = "@STR_COMMON[692]",
    ["STR_ID_PromotionTrojan[10022][Text13]"] = "300 years ago, General Pak was ordered to fight against the Flame Devastator. However, a traitor in his army led to Pak`s unexpected death.",
    ["STR_ID_PromotionTrojan[10022][Text14]"] = "@STR_COMMON[715]",
    ["STR_ID_PromotionTrojan[10022][Text15]"] = "@STR_COMMON[752]",
    ["STR_ID_PromotionTrojan[10022][Text16]"] = "@STR_COMMON[697]",
