    ["STR_ID_PromotionTrojan[10022][Text18]"] = "@STR_COMMON[752]",
    ["STR_ID_PromotionTrojan[10022][Text19]"] = "@STR_COMMON[700]",
    ["STR_ID_PromotionTrojan[10022][Text20]"] = "@STR_COMMON[701]",
    ["STR_ID_PromotionTrojan[10022][Text21]"] = "@STR_COMMON[752]",
    ["STR_ID_PromotionTrojan[10022][Text22]"] = "@STR_COMMON[702]",
    ["STR_ID_PromotionTrojan[10022][Text23]"] = "@STR_COMMON[703]",
    ["STR_ID_PromotionTrojan[10022][Text24]"] = "@STR_COMMON[752]",
    ["STR_ID_PromotionTrojan[10022][Text25]"] = "@STR_COMMON[704]",
    ["STR_ID_PromotionTrojan[10022][Text26]"] = "The XP skills for Trojans are Accuracy, Cyclone and Golem. Accuracy can triple your hit rate; Cyclone can increase your speed; By using the Golem skill, you can transform",
    ["STR_ID_PromotionTrojan[10022][Text27]"] = "Fierce as hurricane, Fatal Cross will crash all blocking the way. While the Mortal Strike holds a devastated power that can cause terrifying damage.",
    ["STR_ID_PromotionTrojan[10022][Text28]"] = "You`ve learned MortalStrike!",
    ["STR_ID_PromotionTrojan[10022][Text29]"] = "You~successfully~acquired~the~skill,~[Mortal~Strike].~Equip~2~Trojan`s~Epic~Weapons~to~cast.~While~attacking,~the~caster~has~a~chance~to~cause~severe~damage~on~human~targets,",
    ["STR_ID_PromotionTrojan[10022][Text30]"] = "~and~more~violent~to~monsters,~within~a~certain~range.",
    ["STR_ID_PromotionTrojan[10022][Text31]"] = "@STR_COMMON[694]",
    ["STR_ID_PromotionTrojan[10022][Text32]"] = "You need to equip a Trojan`s Epic Weapon to learn [MortalStrike].",
    ["STR_ID_PromotionTrojan[10022][Text33]"] = "You`ve~already~acquired~this~skill.",
    ["STR_ID_PromotionTrojan[10022][Text34]"] = "You~successfully~acquired~the~skill,~[Fatal~Cross].~This~active~skill~is~for~Trojan`s~Epic~Weapon~only.",
    ["STR_ID_PromotionTrojan[10022][Text35]"] = "~Equip~2~Epic~Weapons~and~throw~the~Cross~Saber~in~target~direction,~inflicting~damage~on~all~the~targets",
    ["STR_ID_PromotionTrojan[10022][Text36]"] = "~within~2~paces~along~its~attack~path.~Cost:~25~Stamina.",
    ["STR_ID_PromotionTrojan[10022][Text37]"] = "@STR_COMMON[694]",
    ["STR_ID_PromotionTrojan[10022][Text38]"] = "You need to equip a Trojan`s Epic Weapon to learn [Fatal Cross].",
    ["STR_ID_PromotionTrojan[10022][Text39]"] = "@STR_COMMON[705]",
