    -- JiangHuNpc [15745]
    ["STR_ID_JiangHuNpc[15745][Text1]"] = "Well, the Jiang Hu is quite chaotic. I`ll test your understanding with several questions. If you pass, you`re able to name a skill of your own and start your adventure as a Jiang Hu warrior!",
    ["STR_ID_JiangHuNpc[15745][Text2]"] = "Sorry, you not have 2nd Reborn, or you are learning Jiang Hu,",
    ["STR_ID_JiangHuNpc[15745][Text3]"] = "Being a fighter of the Jiang Hu, you can train your Inner-strength after activating `Jiang` button at the character window. Each time you study will cost you 10 Study Points",
    ["STR_ID_JiangHuNpc[15745][Text4]"] = "You need to activate the `Jiang` mode, and defeat a player whose Talent Status is not lower than yours to raise your Status Level by 1,",
    ["STR_ID_JiangHuNpc[15745][Text5]"] = "Jiang Hu fighters will gain up to 100 Free Courses by accumulating the Talent Points over time, whether online or not. The higher the Talent Status,",
    ["STR_ID_JiangHuNpc[15745][Text6]"] = "If you want to leave the Jiang Hu for a while, deactivate the `Jiang` mode and wait for 10 minutes to quit.",

    -- ClanNpc [5533]
    ["STR_ID_ClanNpc[5533][Text1]"] = "The Clan is not only a group, but also a bond between its members! You can have a maximum of 12 members in a clan at one time,",
    -- {0}=(byte)(client.Player.MyClan.Level + 1)
    ["STR_ID_ClanNpc[5533][Text2]"] = "Your current Clan Level is Level {0}",
    -- {0}=Role.Instance.Clan.UpdateLevelAmount[client.Player.MyClan.Level]
    ["STR_ID_ClanNpc[5533][Text3]"] = "~You need {0} Silver`s in the Clan Fund to upgrade the Clan Level.",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_ClanNpc[5533][Text4]"] = "~You can gain BP Bonus Level {0} now: The members can share percent of the Battle Power margin between themselves and",
    -- {0}=client.Player.MyClan.BP
    ["STR_ID_ClanNpc[5533][Text5]"] = "~the highest Battle Power team member in the same map at BP Bonus Level {0}.",
    ["STR_ID_ClanNpc[5533][Text6]"] = "Only~the~Clan~Leader~can~change~the~Guild`s~name,~which~will~take~effect~after~the~server~maintenance~on~the~second~day.~It`ll~cost~you~1075~CPs.~Deal?",
