    -- TheStorekeeper [1]
    ["STR_ID_TheStorekeeper[1][Text1]"] = "I am here selling all kinds of Accessories and Boots. You should not miss the equipment in my shop. ",
    ["STR_ID_TheStorekeeper[1][Text2]"] = "Ah ha? Why don`t you just leave here? Let me guess...You want to buy something? ",
    ["STR_ID_TheStorekeeper[1][Text3]"] = "@STR_COMMON[787]",
    ["STR_ID_TheStorekeeper[1][Text4]"] = "Have you spoken with the Pharmacist? She has all kinds of potions that will be helpful to you in your journey.",
    ["STR_ID_TheStorekeeper[1][Text5]"] = "I have boots, necklaces and rings, which are quite necessary to improve your skills and prowess ",
    ["STR_ID_TheStorekeeper[1][Text6]"] = "@STR_COMMON[788]",
    ["STR_ID_TheStorekeeper[1][Text7]"] = "@STR_COMMON[787]",
    ["STR_ID_TheStorekeeper[1][Text8]"] = "Please make 3 more spaces in your inventory",
    ["STR_ID_TheStorekeeper[1][Text9]"] = "I have told you all I know. I suggest you to find the Pharmacist. She should have something for you there.",

