    -- KungFuKing [17222]
    ["STR_ID_KungFuKing[17222][Text1]"] = "I dare not say I am the best martial artist in the world, but I will never admit I rank the second. ",
    ["STR_ID_KungFuKing[17222][Text2]"] = "@STR_COMMON[790]",
    ["STR_ID_KungFuKing[17222][Text3]"] = "I dare not say I am the best martial artist in the world, but I will never admit I rank the second.",
    ["STR_ID_KungFuKing[17222][Text4]"] = "My hero, you`re chosen by God of Dragon as the new generation for the mythical power.",
    ["STR_ID_KungFuKing[17222][Text5]"] = "Good! Now, I`m transferring my Power of Dragon to you. Feel it, and remember that Dragon`s ",
    ["STR_ID_KungFuKing[17222][Text6]"] = "@STR_COMMON[790]",
    ["STR_ID_KungFuKing[17222][Text7]"] = "There are many things for you to learn in this world! Um, I guess you want to learn more, huh? ",

